  "\"Show Labels\" is \"First Record Only\", so labels are drawn only in the first record unless a feature has Label visibility \"On\".": "فیلد «نمایش برچسب‌ها» روی گزینهٔ «فقط اولین رکورد» تنظیم شده است، بنابراین برچسب‌ها فقط در اولین رکورد ترسیم می‌شوند، مگر اینکه فیلد «قابلیت مشاهدهٔ برچسب» برای یک ویژگی روی گزینهٔ «روشن» باشد.",
  "\"Show Labels\" is \"Top Similarity Group Record\", so labels are drawn only for the features that setting selects, unless a feature has Label visibility \"On\".": "فیلد «نمایش برچسب‌ها» روی گزینهٔ «رکورد برتر گروه شباهت» تنظیم شده است، بنابراین برچسب‌ها فقط برای ویژگی‌هایی ترسیم می‌شوند که آن تنظیم انتخاب می‌کند، مگر اینکه فیلد «قابلیت مشاهدهٔ برچسب» برای یک ویژگی روی گزینهٔ «روشن» باشد.",
