  "A feature": "یک ویژگی",
  "A feature edit does not identify a record of the current inputs. Generate again; if it continues, save a Session for investigation.": "یک ویرایش ویژگی هیچ رکوردی از ورودی‌های فعلی را مشخص نمی‌کند. نقشه را دوباره تولید کنید؛ اگر مشکل ادامه داشت، برای بررسی یک نشست ذخیره کنید.",
  "A file of four or more columns is read as bedGraph: reference, 0-based start, end and value, each end greater than its start, and the rows of a reference in increasing order without overlaps. For samtools depth of several samples, keep the reference, position and one sample's column, or write the file with samtools depth -H.": "فایلی با چهار ستون یا بیشتر به‌صورت bedGraph خوانده می‌شود: توالی مرجع، شروع با شمارش از 0، پایان و مقدار؛ پایان هر ردیف باید بزرگ‌تر از شروع آن باشد و ردیف‌های هر توالی مرجع باید به ترتیب صعودی و بدون هم‌پوشانی باشند. برای خروجی samtools depth از چند نمونه، ستون‌های توالی مرجع و موقعیت و ستون یک نمونه را نگه دارید یا فایل را با samtools depth -H بنویسید.",
  "A genome diagram generator for microbes and organelles": "تولیدکنندهٔ نقشهٔ ژنوم برای میکروب‌ها و اندامک‌ها",
  "A label blacklist is set, and a label whose text contains one of its keywords is not drawn.": "فهرست سیاه برچسب تنظیم شده است و برچسبی که متن آن شامل یکی از کلیدواژه‌های این فهرست باشد ترسیم نمی‌شود.",
  "A label whitelist is set, and labels are drawn only for the features it lists.": "فهرست سفید برچسب تنظیم شده است و برچسب‌ها فقط برای ویژگی‌هایی که در آن آمده‌اند ترسیم می‌شوند.",
  "A new drawing": "یک ترسیم جدید",
  "A part of this feature is on a different strand from the feature.": "یک قسمت از این ویژگی روی رشته‌ای متفاوت از رشتهٔ ویژگی است.",
  "A preserved session setting does not apply to this diagram mode.": "یک تنظیم حفظ‌شدهٔ نشست در این حالت نقشه اعمال نمی‌شود.",
  "A query holds a character that is neither a nucleotide nor an amino acid code. Give DNA, RNA or protein sequences in FASTA: letters, and * for a stop.": "یک توالی query نویسه‌ای دارد که کد نوکلئوتید یا آمینواسید نیست. توالی‌های پروتئین، DNA یا RNA را در قالب FASTA بدهید: حروف و * برای کدون پایان.",
  "A record of this FASTA file has no sequence. Give each FASTA record its sequence.": "یکی از رکوردهای این فایل FASTA توالی ندارد. به هر رکورد FASTA توالی خود را بدهید.",
  "A record of this pair is drawn in several windows, and a BLAST TSV gives the coordinates of one drawn record. Set the pair to Run LOSAT.": "یک رکورد از این جفت در چند پنجره ترسیم شده است و فایل BLAST TSV مختصات یک رکورد ترسیم‌شده را می‌دهد. جفت را روی گزینهٔ «اجرای LOSAT» بگذارید.",
  "A row length of {length} bp should fit (estimated from the drawn height).": "با طول ردیف {length} bp، انتظار می‌رود شکل از این حد فراتر نرود (برآورد بر اساس ارتفاع ترسیم‌شده).",
  "A second row draws {set}.": "ردیف دوم مجموعهٔ {set} را ترسیم می‌کند.",
