  "A selected comparison references a record that is no longer available.": "یک مقایسهٔ انتخاب‌شده به رکوردی اشاره می‌کند که دیگر در دسترس نیست.",
  "A selected feature is not in the displayed Result.": "یک ویژگی انتخاب‌شده در نتیجهٔ نمایش‌داده‌شده نیست.",
  "A tab-separated read-depth table drawn as a track. With several records, one file is used for the same series of every record; a loaded Session keeps each record's Depth TSV as saved, empty ones included.": "جدول عمق خوانش با ستون‌های جداشده با نویسهٔ Tab که به‌صورت ترک ترسیم می‌شود. با چند رکورد، یک فایل برای همان سری هر رکورد استفاده می‌شود؛ نشست بارگذاری‌شده فایل TSV عمق هر رکورد را همان‌طور که ذخیره شده است، از جمله موارد خالی، نگه می‌دارد.",
  "A table row names another displayed record in this column. Swap the query and subject columns of the table, or assign the table to the pair it describes.": "یک ردیف جدول در این ستون به رکورد نمایش‌داده‌شدهٔ دیگری اشاره می‌کند. ستون‌های query و subject جدول را جابه‌جا کنید یا جدول را به جفتی که توصیف می‌کند اختصاص دهید.",
  "A wrapped figure draws no comparisons. Remove the comparison inputs (BLAST, comparison pairs, LOSAT, Similarity groups), or turn Wrap Rows off.": "شکلی که رکوردها را در چند ردیف تقسیم می‌کند، مقایسه‌ای را ترسیم نمی‌کند. ورودی‌های مقایسه (BLAST، جفت‌های مقایسه، LOSAT و گروه‌های شباهت) را بردارید یا علامت «پیچش ردیف‌ها» را بردارید.",
  "A wrapped figure draws no comparisons. Remove the comparison inputs (BLAST, comparison pairs, LOSAT, Similarity groups).": "شکلی که رکوردها را در چند ردیف تقسیم می‌کند، مقایسه‌ای را ترسیم نمی‌کند. ورودی‌های مقایسه (BLAST، جفت‌های مقایسه، LOSAT و حالت «گروه‌های شباهت») را بردارید.",
  "A wrapped record cannot keep a sideways move (from Align at feature, Similarity groups, or a loaded Session). Click Reset record positions under Wrap Rows, or turn Wrap Rows off.": "رکورد پیچانده‌شده نمی‌تواند جابه‌جایی افقی را نگه دارد (از عملیات «تراز کردن بر اساس ویژگی»، حالت «گروه‌های شباهت» یا نشست بارگذاری‌شده). زیر کادر انتخاب «پیچش ردیف‌ها» روی دکمهٔ «بازنشانی موقعیت رکوردها» کلیک کنید یا علامت «پیچش ردیف‌ها» را بردارید.",
  "A wrapped record cannot keep a sideways move (from Align at feature, Similarity groups, or a loaded Session). Click Reset record positions under Wrap Rows.": "رکورد پیچانده‌شده نمی‌تواند جابه‌جایی افقی را نگه دارد (از عملیات «تراز کردن بر اساس ویژگی»، حالت «گروه‌های شباهت» یا نشست بارگذاری‌شده). زیر کادر انتخاب «پیچش ردیف‌ها» روی دکمهٔ «بازنشانی موقعیت رکوردها» کلیک کنید.",
