  "Add {name}": "افزودن {name}",
  "Adding a Depth file, or a series while a Depth file is loaded, turns Show Depth on, and removing the last Depth file or its genome file turns Show Depth off; turning Show Depth off hides the drawn Depth track at once. A changed Legend title clears a Legend tab rename of the old title at once. The rest, and a Depth track from changed files, apply on Generate.": "افزودن فایل عمق، یا سری هنگامی که فایل عمق بارگذاری شده است، گزینهٔ «نمایش عمق» را فعال می‌کند و برداشتن آخرین فایل عمق یا فایل ژنوم آن، گزینهٔ «نمایش عمق» را غیرفعال می‌کند؛ غیرفعال کردن گزینهٔ «نمایش عمق» ترک عمق ترسیم‌شده را بلافاصله پنهان می‌کند. تغییر عنوان راهنما، تغییر نام ثبت‌شده برای عنوان قبلی در زبانهٔ «راهنما» را بلافاصله پاک می‌کند. سایر موارد و ترک عمق حاصل از فایل‌های تغییریافته هنگام تولید اعمال می‌شوند.",
  "Additional horizontal gap ratio between visible content bounds in each row on multi-record canvas. 0 makes row content touch. Default: 0.10 (horizontal only).": "نسبت فاصلهٔ افقی اضافی بین کران‌های محتوای مرئی در هر ردیف در بوم چندرکوردی. مقدار 0 باعث می‌شود محتوای رکوردهای هر ردیف به هم برسد. پیش‌فرض: 0.10 (فقط افقی).",
  "Additional visible gap ratio between row content bounds in multi-record canvas. 0 makes rows touch by content bounds. Default: 0.05 (vertical only).": "نسبت فاصلهٔ مرئی اضافی بین کران‌های محتوای ردیف‌ها در بوم چندرکوردی. 0 باعث می‌شود ردیف‌ها در کران محتوا به هم برسند. پیش‌فرض: 0.05 (فقط عمودی).",
