  "Advanced similarity group settings": "تنظیمات پیشرفتهٔ گروه شباهت",
  "After Apply": "پس از اعمال",
  "Align Similarity Group": "تراز کردن گروه شباهت",
  "Align applies resolved targets immediately; ambiguity opens review. Review alignment options… lets you inspect or change anchors, Skip, and direction before applying.": "عملیات «تراز کردن» اهداف تعیین‌شده را بلافاصله اعمال می‌کند؛ در صورت ابهام، بازبینی باز می‌شود. دکمهٔ «بازبینی گزینه‌های ترازبندی…» به شما امکان می‌دهد پیش از اعمال، لنگرها، گزینهٔ «رد شدن» و جهت را بررسی یا تغییر دهید.",
  "Align at feature": "تراز کردن بر اساس ویژگی",
  "Align at feature cannot line up these records while Wrap Rows cuts a record into rows: it would move a cut record sideways, or line the others up with the feature of a cut record that it does not rotate. Only a complete circular record is aligned by rotation and can be wrapped. Turn Wrap Rows off, then use Align at feature.": "وقتی گزینهٔ «پیچش ردیف‌ها» یک رکورد را به چند ردیف تقسیم می‌کند، عملیات «تراز کردن بر اساس ویژگی» نمی‌تواند این رکوردها را تراز کند: این عملیات رکورد تقسیم‌شده را به‌صورت افقی جابه‌جا می‌کند یا رکوردهای دیگر را با ویژگی رکورد تقسیم‌شده‌ای تراز می‌کند که آن را نمی‌چرخاند. فقط یک رکورد حلقوی کامل با چرخش تراز می‌شود و می‌تواند پیچانده شود. علامت «پیچش ردیف‌ها» را بردارید، سپس از عملیات «تراز کردن بر اساس ویژگی» استفاده کنید.",
  "Align at feature writes each record's start on its own File card, and these records share one File card (a file with several records). Click Generate Diagram, which gives each record its own File card, then use Align at feature again.": "عملیات «تراز کردن بر اساس ویژگی» موقعیت شروع هر رکورد را روی کارت فایل مخصوص آن می‌نویسد، اما این رکوردها یک کارت فایل مشترک دارند (فایلی با چند رکورد). روی دکمهٔ «تولید نقشه» کلیک کنید تا هر رکورد کارت فایل مخصوص خود را داشته باشد، سپس دوباره از عملیات «تراز کردن بر اساس ویژگی» استفاده کنید.",
  "Align at feature…": "تراز کردن بر اساس ویژگی…",
