  "Annotation id \"{text}\" is used by another annotation of this set, so it was saved as \"{stored}\".": "شناسهٔ حاشیه‌نویسی «{text}» در حاشیه‌نویسی دیگری از این مجموعه استفاده شده است، بنابراین به‌صورت «{stored}» ذخیره شد.",
  "Annotation id cannot be empty, so it was saved as \"{stored}\".": "شناسهٔ حاشیه‌نویسی نمی‌تواند خالی باشد، بنابراین به‌صورت «{stored}» ذخیره شد.",
