  "Applied {count} feature edit.": "{count} ویرایش ویژگی اعمال شد.",
  "Applied {count} feature edits.": {"one": "{count} ویرایش ویژگی اعمال شد.", "other": "{count} ویرایش ویژگی اعمال شد."},
  "Applies now, also over the queued palette.": "اکنون اعمال می‌شود و بر پالت در صف نیز اولویت دارد.",
  "Applies on Generate": "هنگام تولید اعمال می‌شود",
  "Applies on Generate, except turning a GC content, GC skew or Depth row on or off, removing one, and Use custom stack, which apply at once. These still apply on Generate: turning on a row added since the last Generate, a row that was off when the Session was loaded, or a Depth row after a Depth file change; and Use custom stack after a Session load (except when turned off on a Linear Result drawn with it) or while the Region Annotation sets differ from those of the Result, with every track it would hide or show.": "هنگام تولید اعمال می‌شود، به‌جز روشن یا خاموش کردن ردیف محتوای GC، ردیف GC skew یا ردیف عمق، برداشتن یکی از آن‌ها و گزینهٔ «استفاده از پشتهٔ سفارشی» که بلافاصله اعمال می‌شوند. این موارد همچنان هنگام تولید اعمال می‌شوند: روشن کردن ردیفی که پس از آخرین تولید افزوده شده است، ردیفی که هنگام بارگذاری نشست خاموش بوده است یا ردیف عمق پس از تغییر فایل عمق؛ و گزینهٔ «استفاده از پشتهٔ سفارشی» پس از بارگذاری نشست (مگر هنگام خاموش کردن آن در نتیجهٔ نقشهٔ خطی که با آن ترسیم شده است) یا تا زمانی که مجموعه‌های حاشیه‌نویسی ناحیه با مجموعه‌های نتیجه تفاوت دارند، همراه با هر ترکی که پنهان یا نمایان می‌کند.",
  "Applies the live circular track arrangement used while Custom Track Slots is off. Custom Track Slots inherit this preset when enabled.": "چیدمان زندهٔ ترک‌های نقشهٔ حلقوی را اعمال می‌کند؛ این چیدمان تا وقتی «اسلات‌های ترک سفارشی» غیرفعال است به کار می‌رود. «اسلات‌های ترک سفارشی» هنگام فعال شدن، این پیش‌تنظیم را به ارث می‌برند.",
  "Applies to SVG and Interactive SVG exports, not to Generate.": "روی خروجی‌های SVG و SVG تعاملی اعمال می‌شود و هنگام تولید اعمال نمی‌شود.",
