  "Auto": "خودکار",
  "Auto (32)": "خودکار (32)",
  "Auto (Default)": "خودکار (پیش‌فرض)",
  "Auto (by genome size)": "خودکار (بر اساس اندازهٔ ژنوم)",
  "Auto ({count} parallel run)": "خودکار ({count} اجرای موازی)",
  "Auto ({count} parallel runs)": {"one": "خودکار ({count} اجرای موازی)", "other": "خودکار ({count} اجرای موازی)"},
  "Auto ({count})": "خودکار ({count})",
  "Auto ({mode})": "خودکار ({mode})",
  "Auto ({value})": "خودکار ({value})",
  "Auto Reflow": "چینش مجدد خودکار",
  "Auto Reflow failed. Current diagram is kept.": "عملیات «چینش مجدد خودکار» انجام نشد. نقشهٔ فعلی نگه داشته شد.",
  "Auto embeds labels that fit and routes the rest externally. Embedded Only drops labels that need external placement. External Only keeps labels outside feature bodies.": "گزینهٔ «خودکار» برچسب‌هایی را که در ویژگی جا می‌شوند جاسازی می‌کند و بقیه را به خارج هدایت می‌کند. گزینهٔ «فقط جاسازی‌شده» برچسب‌هایی را که به جانمایی خارجی نیاز دارند نمایش نمی‌دهد. گزینهٔ «فقط خارجی» برچسب‌ها را خارج از بدنهٔ ویژگی‌ها نگه می‌دارد.",
  "Auto follows the track layout (Above or Features on axis: labels above; Below: labels below). Above Feature draws labels above features (and below negative-strand features when Separate Strands is on).": "گزینهٔ «خودکار» از طرح‌بندی ترک پیروی می‌کند (گزینه‌های «بالا» یا «ویژگی‌ها روی محور»: برچسب‌ها در بالا؛ گزینهٔ «پایین»: برچسب‌ها در پایین). گزینهٔ «بالای ویژگی» برچسب‌ها را بالای ویژگی‌ها ترسیم می‌کند؛ اگر گزینهٔ «جدا کردن رشته‌ها» فعال باشد، برچسب‌های ویژگی‌های رشتهٔ معکوس زیر آن ویژگی‌ها ترسیم می‌شوند.",
  "Auto hides these fields throughout the diagram": "گزینهٔ «خودکار» این فیلدها را در سراسر نقشه پنهان می‌کند",
  "Auto makes the CDSs that share a locus identifier one unit and every other CDS a unit of its own. CDS makes each CDS a unit. Locus makes each locus a unit and requires a locus identifier, such as /locus_tag, on every CDS.": "با گزینهٔ «خودکار»، ویژگی‌های CDS دارای شناسهٔ جایگاه مشترک یک واحد در نظر گرفته می‌شوند و هر ویژگی CDS دیگر یک واحد مستقل است. با گزینهٔ «CDS»، هر ویژگی CDS یک واحد در نظر گرفته می‌شود. با گزینهٔ «جایگاه»، هر جایگاه یک واحد در نظر گرفته می‌شود و هر ویژگی CDS باید شناسهٔ جایگاه، مانند /locus_tag، داشته باشد.",
  "Auto runs threaded LOSAT when this browser supports it, and serial LOSAT otherwise. LOSATN task dc-megablast needs threaded LOSAT.": "با گزینهٔ «خودکار»، اگر این مرورگر از LOSAT چندریسمانی پشتیبانی کند، LOSAT به‌صورت چندریسمانی و در غیر این صورت به‌صورت ترتیبی اجرا می‌شود. وظیفهٔ dc-megablast در LOSATN به LOSAT چندریسمانی نیاز دارد.",
  "Auto shows these fields throughout the diagram": "گزینهٔ «خودکار» این فیلدها را در سراسر نقشه نشان می‌دهد",
  "Auto will hide these fields throughout the diagram on the next successful Generate": "گزینهٔ «خودکار» هنگام تولید موفق بعدی، این فیلدها را در سراسر نقشه پنهان خواهد کرد",
  "Auto will show these fields throughout the diagram on the next successful Generate": "گزینهٔ «خودکار» هنگام تولید موفق بعدی، این فیلدها را در سراسر نقشه نشان خواهد داد",
  "Auto · Hidden": "خودکار · پنهان",
  "Auto · Shown": "خودکار · نمایان",
  "Automatic (no explicit selector)": "خودکار (بدون انتخاب‌گر صریح)",
  "Automatic (single record)": "خودکار (یک رکورد)",
  "Automatic diagram fitting and zoom may move records on screen.": "متناسب‌سازی خودکار نقشه و بزرگ‌نمایی ممکن است رکوردها را روی صفحه جابه‌جا کند.",
  "Available ({count})": "در دسترس ({count})",
