  "Base text shown in the diagram legend. Leave blank to use the auto label shown here; two-color tracks add (+) and (-).": "متن پایه‌ای که در راهنمای نقشه نمایش داده می‌شود. برای استفاده از برچسب خودکار نمایش‌داده‌شده در اینجا خالی بگذارید؛ ترک‌های دورنگ (+) و (-) را اضافه می‌کنند.",
