  "Changing \"{setting}\" to \"{value}\" removes the lane for {count} features you placed manually.": {"one": "تغییر تنظیم «{setting}» به «{value}» لاین {count} ویژگی را که دستی جانمایی کرده‌اید برمی‌دارد.", "other": "تغییر تنظیم «{setting}» به «{value}» لاین {count} ویژگی را که دستی جانمایی کرده‌اید برمی‌دارد."},
