  "Choose BLAST TSV for {name}": "انتخاب فایل BLAST TSV برای {name}",
  "Choose Error on overflow, Compress, or Clip.": "گزینهٔ «خطا هنگام سرریز»، «فشرده‌سازی» یا «بریدن» را انتخاب کنید.",
  "Choose Foreground or Underlay.": "گزینهٔ «پیش‌زمینه» یا «زیرلایه» را انتخاب کنید.",
  "Choose LOSATN or TLOSATX for comparison rings.": "برای حلقه‌های مقایسه، LOSATN یا TLOSATX را انتخاب کنید.",
  "Choose Pairwise matches, Similarity groups, or Collinear blocks.": "گزینهٔ «تطابق‌های دوبه‌دو»، «گروه‌های شباهت» یا «بلوک‌های هم‌خط» را انتخاب کنید.",
  "Choose Show in Record Labels to keep a field visible.": "گزینهٔ «نمایش» را در بخش «برچسب‌های رکورد» انتخاب کنید تا فیلد قابل مشاهده بماند.",
  "Choose Strand or Gene order.": "گزینهٔ «رشته» یا «ترتیب ژن‌ها» را انتخاب کنید.",
  "Choose a BLAST TSV for this pair, or set the pair to No comparison or Run LOSAT.": "برای این جفت یک فایل BLAST TSV انتخاب کنید یا جفت را روی گزینهٔ «بدون مقایسه» یا «اجرای LOSAT» بگذارید.",
  "Choose a LOSATN task that the selected LOSAT runtime supports.": "وظیفه‌ای از LOSATN را انتخاب کنید که محیط اجرای LOSAT انتخاب‌شده از آن پشتیبانی می‌کند.",
  "Choose a Record before setting a region on a multi-record file.": "پیش از تنظیم ناحیه روی فایل چندرکوردی، یک رکورد انتخاب کنید.",
  "Choose a candidate or Skip for {count} record.": "برای {count} رکورد، یک نامزد انتخاب کنید یا گزینهٔ «رد شدن» را انتخاب کنید.",
  "Choose a candidate or Skip for {count} records.": {"one": "برای هر یک از {count} رکورد، یک نامزد انتخاب کنید یا گزینهٔ «رد شدن» را انتخاب کنید.", "other": "برای هر یک از {count} رکورد، یک نامزد انتخاب کنید یا گزینهٔ «رد شدن» را انتخاب کنید."},
  "Choose a crop or an explicit display start.": "یک برش یا یک شروع نمایش صریح انتخاب کنید.",
  "Choose a drawing other than the shown one.": "ترسیمی غیر از ترسیم نمایش‌داده‌شده را انتخاب کنید.",
  "Choose a feature": "یک ویژگی انتخاب کنید",
  "Choose a feature of {name}.": "یک ویژگی از رکورد {name} انتخاب کنید.",
  "Choose a feature-start, anchor, or feature-end placement.": "یکی از جانمایی‌ها (در ابتدای ویژگی، روی لنگر یا در انتهای ویژگی) را انتخاب کنید.",
  "Choose a fix": "انتخاب راه رفع",
  "Choose a gbdraw Session file.": "یک فایل نشست gbdraw انتخاب کنید.",
  "Choose a gene": "انتخاب ژن",
  "Choose a nucleotide, protein, or translated nucleotide search. LOSATP settings are preserved while another mode is active.": "جستجوی نوکلئوتید، پروتئین یا نوکلئوتید ترجمه‌شده را انتخاب کنید. تنظیمات LOSATP تا زمانی که حالت دیگری فعال است حفظ می‌شوند.",
  "Choose a readable TrueType or OpenType font file ({trueType}, {openType}, {trueTypeCollection}, {openTypeCollection}) that names its font family.": "یک فایل قلم TrueType یا OpenType قابل خواندن ({trueType}، {openType}، {trueTypeCollection} و {openTypeCollection}) انتخاب کنید که نام خانوادهٔ قلم را مشخص می‌کند.",
  "Choose a record": "یک رکورد انتخاب کنید",
