  "Choose anchor_core_v1.": "مقدار anchor_core_v1 را انتخاب کنید.",
  "Choose at least one record.": "دست‌کم یک رکورد انتخاب کنید.",
  "Choose each feature type's rendering. Underlay removes it from feature lanes and labels, then highlights each feature's span across the full thickness of the feature track, behind foreground features.": "ترسیم هر نوع ویژگی را انتخاب کنید. گزینهٔ «زیرلایه» آن را از لاین‌ها و برچسب‌های ویژگی برمی‌دارد، سپس بازهٔ هر ویژگی را پشت ویژگی‌های پیش‌زمینه، در تمام ضخامت ترک ویژگی برجسته می‌کند.",
  "Choose file": "انتخاب فایل",
  "Choose file for {pair}": "انتخاب فایل برای {pair}",
  "Choose file…": "انتخاب فایل…",
  "Choose from color rules…": "از قوانین رنگ انتخاب کنید…",
  "Choose how protein matches are presented. Similarity groups and Collinear blocks require all-adjacent LOSAT.": "نحوهٔ ارائهٔ تطابق‌های پروتئین را انتخاب کنید. حالت‌های «گروه‌های شباهت» و «بلوک‌های هم‌خط» به جستجوی LOSAT برای همهٔ جفت‌های مجاور نیاز دارند.",
  "Choose how to handle the saved comparison in the Comparison panel, then Generate again.": "نحوهٔ برخورد با مقایسهٔ ذخیره‌شده را در بخش «مقایسه» انتخاب کنید، سپس نقشه را دوباره تولید کنید.",
  "Choose input containing CDS proteins.": "ورودی‌ای شامل پروتئین‌های CDS انتخاب کنید.",
  "Choose installed font": "انتخاب قلم نصب‌شده",
  "Choose installed font…": "انتخاب قلم نصب‌شده…",
  "Choose or type a qualifier. A rule without one colors nothing.": "یک qualifier انتخاب یا تایپ کنید. قانونی که qualifier نداشته باشد هیچ چیزی را رنگ نمی‌کند.",
  "Choose record pairs that the LOSAT search can run: two or more records, LOSAT rows only with a LOSAT program, and LOSATP Pairwise for selected pairs.": "جفت‌های رکوردی را انتخاب کنید که بتوان جستجوی LOSAT را برای آن‌ها اجرا کرد: دو رکورد یا بیشتر، ردیف‌های LOSAT فقط با برنامهٔ LOSAT و حالت «تطابق‌های دوبه‌دو» در LOSATP برای جفت‌های انتخاب‌شده.",
  "Choose records": "انتخاب رکوردها",
  "Choose records…": "انتخاب رکوردها…",
  "Choose several or drop them here.": "چند فایل را انتخاب کنید یا اینجا رها کنید.",
  "Choose the gene to line up, or skip this record.": "ژنی را که باید در یک راستا قرار گیرد انتخاب کنید یا برای این رکورد گزینهٔ «رد شدن» را انتخاب کنید.",
  "Choose the placement Overlay anchor (Circular) or On axis (Linear) when an anchor or an Extend to slot is selected.": "هنگامی که لنگر یا اسلاتی در فیلد «گسترش تا» انتخاب شده است، برای جانمایی گزینهٔ «روی لنگر» (نقشهٔ حلقوی) یا «روی محور» (نقشهٔ خطی) را انتخاب کنید.",
  "Choose the record of each reference window.": "رکورد هر پنجرهٔ مرجع را انتخاب کنید.",
  "Choose the record that this annotation targets.": "رکورد هدف این حاشیه‌نویسی را انتخاب کنید.",
