  "Color": "رنگ",
  "Color Change Scope": "دامنهٔ تغییر رنگ",
  "Color features whose qualifier value matches a regular expression, case-insensitive (for example NADH). Choose a suggested qualifier or type any qualifier name. When rules use the same qualifier, the first matching row wins; Move rule up and down changes that order. Rules on different qualifiers are tried in the order the qualifiers appear on the feature.": "ویژگی‌هایی را رنگ کنید که مقدار qualifier آن‌ها با یک عبارت باقاعده مطابقت دارد، بدون حساسیت به حروف کوچک و بزرگ (برای مثال NADH). یک qualifier پیشنهادی را انتخاب کنید یا نام هر qualifier را تایپ کنید. وقتی چند قانون از یک qualifier استفاده می‌کنند، اولین ردیفی که مطابقت داشته باشد اعمال می‌شود؛ دکمه‌های «انتقال قانون به بالا» و «انتقال قانون به پایین» این ترتیب را تغییر می‌دهند. قانون‌هایی که qualifier متفاوت دارند به ترتیب ظاهر شدن qualifier در ویژگی بررسی می‌شوند.",
