  "Conservation rings are not drawn when several records share one circle.": "وقتی چند رکورد یک دایره را به اشتراک می‌گذارند، حلقه‌های حفاظت‌شدگی ترسیم نمی‌شوند.",
  "Content plot": "نمودار محتوا",
  "Control label visibility, filtering, text settings, and circular label geometry.": "قابلیت مشاهدهٔ برچسب، فیلتر کردن، تنظیمات متن و هندسهٔ برچسب‌های نقشهٔ حلقوی را کنترل کنید.",
  "Control track placement and layout-related options.": "جانمایی ترک و گزینه‌های مرتبط با طرح‌بندی را کنترل کنید.",
  "Control which feature labels are displayed using Blacklist or Whitelist. Whitelist patterns use case-insensitive Python regex search, matching the -t color table semantics.": "با استفاده از گزینهٔ «فهرست سیاه» یا «فهرست سفید» کنترل کنید کدام برچسب‌های ویژگی نمایش داده شوند. الگوهای فهرست سفید از جستجوی عبارت باقاعدهٔ Python بدون حساسیت به حروف کوچک و بزرگ استفاده می‌کنند، مطابق با رفتار جدول رنگ -t.",
  "Converting LOSAT protein hits...": "در حال تبدیل تطابق‌های پروتئینی LOSAT…",
  "Converting LOSAT protein links to collinear ribbons...": "در حال تبدیل پیوندهای پروتئینی LOSAT به روبان‌های هم‌خط…",
  "Coordinates": "مختصات",
  "Coordinates exceed the sequence length ({length} bp).": "مختصات از طول توالی ({length} bp) فراتر می‌روند.",
  "Coordinates must be greater than or equal to 1.": "مختصات باید بزرگ‌تر یا مساوی 1 باشند.",
  "Coordinates must be whole 1-based values.": "مختصات باید مقادیری صحیح با شمارش از 1 باشند.",
  "Coordinates refer to the original record.": "مختصات مربوط به رکورد اصلی هستند.",
  "Copied FASTA": "متن FASTA کپی شد",
  "Copied!": "کپی شد!",
  "Copies the chosen records or regions of the shown drawing to a new drawing, or adds them below the records of an existing drawing. In a new drawing, whole records keep the drawing mode, several Circular records as one Multi-Record Canvas; a range makes a Linear drawing unless one range alone is drawn Circular. Coordinates are 1-based and inclusive, in source coordinates.": "رکوردها یا ناحیه‌های انتخاب‌شدهٔ ترسیم نمایش‌داده‌شده را در یک ترسیم جدید کپی می‌کند یا آن‌ها را زیر رکوردهای یک ترسیم موجود اضافه می‌کند. در ترسیم جدید، رکوردهای کامل حالت ترسیم خود را نگه می‌دارند و چند رکورد نقشهٔ حلقوی به‌صورت یک «بوم چندرکوردی» درمی‌آیند؛ یک بازه ترسیم خطی می‌سازد، مگر اینکه یک بازهٔ تنها به‌صورت حلقوی ترسیم شود. مختصات از 1 شمرده می‌شوند، دو سر را شامل می‌شوند و بر پایهٔ مختصات منبع هستند.",
