  "Custom stack Depth rows control rendering. Disable the custom stack to change this simple control.": "در پشتهٔ سفارشی، ردیف‌های عمق ترسیم را کنترل می‌کنند. برای تغییر این کنترل ساده، پشتهٔ سفارشی را غیرفعال کنید.",
  "Custom stack geometry is active. Use each Depth row width, or Reset to copy this value into the stack.": "هندسهٔ پشتهٔ سفارشی فعال است. از عرض هر ردیف عمق استفاده کنید یا با دکمهٔ «بازنشانی» این مقدار را در پشته کپی کنید.",
  "Custom stack geometry is active. Use the Dinucleotide content row radius, or Reset to copy this value into the stack.": "هندسهٔ پشتهٔ سفارشی فعال است. از شعاع ردیف «محتوای دی‌نوکلئوتید» استفاده کنید یا با دکمهٔ «بازنشانی» این مقدار را در پشته کپی کنید.",
  "Custom stack geometry is active. Use the Dinucleotide content row width, or Reset to copy this value into the stack.": "هندسهٔ پشتهٔ سفارشی فعال است. از عرض ردیف «محتوای دی‌نوکلئوتید» استفاده کنید یا با دکمهٔ «بازنشانی» این مقدار را در پشته کپی کنید.",
  "Custom stack geometry is active. Use the Dinucleotide skew row radius, or Reset to copy this value into the stack.": "هندسهٔ پشتهٔ سفارشی فعال است. از شعاع ردیف «دی‌نوکلئوتید skew» استفاده کنید یا با دکمهٔ «بازنشانی» این مقدار را در پشته کپی کنید.",
  "Custom stack geometry is active. Use the Dinucleotide skew row width, or Reset to copy this value into the stack.": "هندسهٔ پشتهٔ سفارشی فعال است. از عرض ردیف «دی‌نوکلئوتید skew» استفاده کنید یا با دکمهٔ «بازنشانی» این مقدار را در پشته کپی کنید.",
  "Custom stack geometry is active. Use the Features row width, or Reset to copy this value into the stack.": "هندسهٔ پشتهٔ سفارشی فعال است. از عرض ردیف «ویژگی‌ها» استفاده کنید یا با دکمهٔ «بازنشانی» این مقدار را در پشته کپی کنید.",
