  "Draw all records one after another on one circle.": "همهٔ رکوردها را پشت سر هم روی یک دایره ترسیم کنید.",
  "Draw all sequences at the same displayed length. Hides the length bar.": "همهٔ توالی‌ها را با طول نمایشی یکسان ترسیم کنید. نوار طول را پنهان می‌کند.",
  "Draw each record over rows of this length. Leave the length empty for Auto, which chooses it from the longest record.": "هر رکورد را در ردیف‌هایی با این طول ترسیم کنید. برای «خودکار» فیلد طول را خالی بگذارید؛ در این حالت طول بر اساس طولانی‌ترین رکورد انتخاب می‌شود.",
  "Draw one circular pairwise comparison ring per uploaded BLAST outfmt 6/7 file or browser LOSATN/TLOSATX comparison sequence file (FASTA, GenBank, or DDBJ). Reverse BLAST coordinates are shown as reverse hits, not origin-spanning hits.": "برای هر فایل BLAST outfmt 6/7 بارگذاری‌شده یا هر فایل توالی مقایسه (FASTA، GenBank یا DDBJ) برای مقایسهٔ LOSATN/TLOSATX در مرورگر، یک حلقهٔ مقایسهٔ دوبه‌دو در نقشهٔ حلقوی ترسیم کنید. مختصات معکوس BLAST به‌صورت تطابق‌های معکوس نشان داده می‌شوند، نه تطابق‌هایی که از مبدأ عبور می‌کنند.",
  "Draw records": "ترسیم رکوردها",
  "Draw the comparison rings. Generate runs their comparisons only while this is on.": "حلقه‌های مقایسه را ترسیم کنید. مقایسه‌های آن‌ها هنگام تولید فقط در صورتی اجرا می‌شوند که این گزینه فعال باشد.",
  "Draw this record": "ترسیم این رکورد",
  "Draw {set} again": "ترسیم دوبارهٔ مجموعهٔ {set}",
  "Drawing": "ترسیم",
  "Drawing menu for {name}": "منوی ترسیم {name}",
  "Drawing name": "نام ترسیم",
  "Drawings": "ترسیم‌ها",
  "Draws each label that the label priority names from the gene qualifier in italics, also after its text is edited. Other labels stay upright.": "هر برچسبی را که طبق اولویت qualifier از qualifier gene گرفته می‌شود، حتی پس از ویرایش متن، به‌صورت مورب ترسیم می‌کند. برچسب‌های دیگر غیرمورب می‌مانند.",
  "Duplicate": "تکثیر",
  "Duplicate drawing": "تکثیر ترسیم",
  "Duplicate set": "تکثیر مجموعه",
  "Duplicate track": "تکثیر ترک",
  "Duplicate track {id}": "تکثیر ترک {id}",
  "Duplicating this row would make the custom stack invalid": "تکثیر این ردیف، پشتهٔ سفارشی را نامعتبر می‌کند",
  "E-value": "E-value",
  "E-value ≤ {value}": "حداکثر E-value: {value}",
  "Each file becomes one row of the new drawing. Untick a window to leave it out.": "هر فایل یک ردیف از ترسیم جدید می‌شود. علامت کادر انتخاب یک پنجره را بردارید تا کنار گذاشته شود.",
  "Each file is used for every record.": "هر فایل برای همهٔ رکوردها استفاده می‌شود.",
  "Each selected pair must join two different available records on adjacent rows, and appear once.": "هر جفت انتخاب‌شده باید دو رکورد متفاوت و در دسترس را در ردیف‌های مجاور به هم وصل کند و فقط یک بار ظاهر شود.",
  "Each track counts the features one query finds in each window of every record, as a heatmap or a histogram. The query is a feature type (* for every type), with an optional qualifier, value regex and length range.": "هر ترک ویژگی‌هایی را که یک جستار در هر پنجرهٔ هر رکورد پیدا می‌کند می‌شمارد و تعداد آن‌ها را به‌صورت نقشهٔ حرارتی یا هیستوگرام نشان می‌دهد. این جستار یک نوع ویژگی است (* برای همهٔ انواع) و می‌تواند به‌طور اختیاری qualifier، عبارت باقاعدهٔ مقدار و محدودهٔ طول را هم داشته باشد.",
  "Each wrapped row draws a ruler on its axis. Set Scale Style to Ruler (Ticks), or turn Wrap Rows off.": "هر ردیف پیچانده‌شده روی محور خود یک خط‌کش ترسیم می‌کند. فیلد «سبک مقیاس» را روی گزینهٔ «خط‌کش (تیک)» بگذارید یا علامت «پیچش ردیف‌ها» را بردارید.",
  "Edge kind": "نوع یال",
  "Edit": "ویرایش",
  "Edit Species / Strain…": "ویرایش گونه / سویه…",
  "Edit feature visibility rule": "ویرایش قانون قابلیت مشاهدهٔ ویژگی",
  "Edit label text": "ویرایش متن برچسب",
  "Edit pattern": "ویرایش الگو",
  "Edit record definition": "ویرایش تعریف رکورد",
  "Edit setting": "ویرایش تنظیم",
  "Edit specific color rule": "ویرایش قانون رنگ خاص",
  "Edit the explicit circular stack. Opening or closing this panel does not enable or alter the stack. Rows above Axis render outside and rows below Axis render inside.": "پشتهٔ صریح نقشهٔ حلقوی را ویرایش کنید. باز یا بسته کردن این پنل پشته را نه فعال می‌کند و نه تغییر می‌دهد. ردیف‌های بالای «محور» در خارج محور و ردیف‌های پایین «محور» در داخل آن ترسیم می‌شوند.",
  "Edit the explicit linear track stack. Opening or closing this panel does not enable or alter the stack. Arrows reorder within the current side; Row actions move rows across the boundary.": "پشتهٔ صریح ترک‌های نقشهٔ خطی را ویرایش کنید. باز یا بسته کردن این پنل پشته را نه فعال می‌کند و نه تغییر می‌دهد. دکمه‌های پیکان ترتیب را در همان سمت فعلی تغییر می‌دهند؛ منوی «عملیات ردیف» ردیف‌ها را از مرز محور عبور می‌دهد.",
  "Edit this record in its File card in the sidebar.": "این رکورد را در کارت فایل آن در نوار کناری ویرایش کنید.",
