  "Feature metadata recovery currently supports GenBank-backed sessions only. Generate the diagram again to enable feature editing.": "بازیابی فرادادهٔ ویژگی در حال حاضر فقط از نشست‌های مبتنی بر GenBank پشتیبانی می‌کند. برای فعال شدن ویرایش ویژگی، نقشه را دوباره تولید کنید.",
