  "Files cannot be moved while Record Layout does not give each File its own consecutive rows. Change the rows in Record Layout under Advanced comparison and layout.": "تا زمانی که بخش «طرح‌بندی رکورد» به هر فایل ردیف‌های متوالی مخصوص خود را ندهد، فایل‌ها قابل انتقال نیستند. ردیف‌ها را در بخش «مقایسه و طرح‌بندی پیشرفته» (بخش «طرح‌بندی رکورد») تغییر دهید.",
  "Files in this Session": "فایل‌های موجود در این نشست",
