  "Filter browser LOSAT alignments before drawing comparison rings.": "هم‌ترازی‌های LOSAT در مرورگر را پیش از ترسیم حلقه‌های مقایسه فیلتر کنید.",
  "Filter uploaded BLAST alignments before drawing comparison rings.": "هم‌ترازی‌های BLAST بارگذاری‌شده را پیش از ترسیم حلقه‌های مقایسه فیلتر کنید.",
