  "Fix": "راه رفع",
  "Fix before Generate": "رفع پیش از تولید",
  "Fix the identity color scale so figures with different thresholds share colors and Legend labels. Leave the minimum blank to color from the minimum identity to 100%.": "مقیاس رنگ همسانی را ثابت کنید تا شکل‌هایی با آستانه‌های متفاوت رنگ‌ها و برچسب‌های راهنمای یکسانی داشته باشند. برای رنگ‌آمیزی از حداقل همسانی تا 100%، حداقل را خالی بگذارید.",
  "Fixed while Wrap Rows is on.": "تا وقتی گزینهٔ «پیچش ردیف‌ها» فعال است، ثابت می‌ماند.",
  "Font": "قلم",
  "Font size": "اندازهٔ قلم",
  "Font size for GC content percent tick labels. Leave blank for auto.": "اندازهٔ قلم برچسب‌های تیک درصد محتوای GC. برای مقدار خودکار خالی بگذارید.",
  "Font size for circular tick labels. Leave blank to use the default size.": "اندازهٔ قلم برچسب‌های تیک نقشهٔ حلقوی. برای استفاده از اندازهٔ پیش‌فرض خالی بگذارید.",
  "Font size for feature labels.": "اندازهٔ قلم برای برچسب‌های ویژگی.",
  "Font size for record-label text (species/strain in circular; organism/replicon/accession/length stack in linear).": "اندازهٔ قلم برای متن برچسب رکورد (گونه/سویه در نقشهٔ حلقوی؛ سطرهای جاندار/رپلیکون/شمارهٔ دسترسی/طول که در نقشهٔ خطی زیر هم قرار می‌گیرند).",
  "Font size for ruler tick labels, including rulers drawn on record axes.": "اندازهٔ قلم برچسب تیک خط‌کش، از جمله خط‌کش‌های ترسیم‌شده روی محور رکوردها.",
  "Font size for the circular shared plot title. Only used when the title position is Top or Bottom.": "اندازهٔ قلم برای عنوان مشترک نمودار نقشهٔ حلقوی. فقط وقتی موقعیت عنوان روی گزینهٔ «بالا» یا «پایین» باشد استفاده می‌شود.",
  "Font size for the legend text.": "اندازهٔ قلم برای متن راهنما.",
  "Font size for the linear plot title.": "اندازهٔ قلم برای عنوان نمودار نقشهٔ خطی.",
  "Font size for the simple bar scale label.": "اندازهٔ قلم برچسب نوار مقیاس ساده.",
  "Font size for this track's depth tick labels. Leave blank for auto.": "اندازهٔ قلم برچسب‌های تیک عمق این ترک. برای مقدار خودکار خالی بگذارید.",
  "Font {family} could not be prepared for the PDF. Its text is drawn in {substitute}.": "قلم {family} برای خروجی PDF آماده نشد. متن آن با قلم {substitute} ترسیم می‌شود.",
  "Font {family} is not embedded in the PDF: its license (OS/2 fsType) does not allow embedding. Its text is drawn in {substitute}.": "قلم {family} در خروجی PDF جاسازی نمی‌شود: مجوز آن (OS/2 fsType) اجازهٔ جاسازی نمی‌دهد. متن آن با قلم {substitute} ترسیم می‌شود.",
  "Font {family} is not embedded: its license (OS/2 fsType) does not allow embedding. The SVG shows it only where {family} is installed.": "قلم {family} جاسازی نشده است: مجوز آن (OS/2 fsType) جاسازی را مجاز نمی‌داند. فایل SVG آن را فقط در جایی نشان می‌دهد که قلم {family} نصب باشد.",
  "Fonts loaded in this page could not be prepared again for drawing. Load them again in Font, or choose another font.": "قلم‌های بارگذاری‌شده در این صفحه دوباره برای ترسیم آماده نشد. آن‌ها را دوباره در بخش «قلم» بارگذاری کنید یا قلم دیگری انتخاب کنید.",
  "For Extend to, select an eligible enabled slot other than the anchor, or None.": "در فیلد «گسترش تا»، یک اسلات فعال واجد شرایط غیر از لنگر یا گزینهٔ «هیچ‌کدام» را انتخاب کنید.",
  "For a window across the origin, enter a Start greater than the End.": "برای پنجره‌ای که از مبدأ می‌گذرد، در فیلد «شروع» عددی بزرگ‌تر از مقدار فیلد «پایان» وارد کنید.",
  "Foreground": "پیش‌زمینه",
  "Found in part: {genes}.": "به‌طور جزئی یافت شد: {genes}.",
  "Free up disk space, or close private windows, then save again.": "فضای دیسک آزاد کنید یا پنجره‌های خصوصی را ببندید، سپس دوباره ذخیره کنید.",
