  "Gap between axis and nearest feature edge for Above/Below track layouts. Auto derives from feature height.": "فاصلهٔ بین محور و نزدیک‌ترین لبهٔ ویژگی در طرح‌بندی‌های ترک «بالا» و «پایین». با خالی ماندن فیلد (خودکار)، این فاصله از ارتفاع ویژگی محاسبه می‌شود.",
  "Gap between records (degrees)": "فاصلهٔ بین رکوردها (درجه)",
  "Gap between the records of one row. Blank (Auto): {gap} px, narrowed in a row whose gaps would take more than {share}% of its width. A gap you type is kept; when a row cannot hold it, Generate stops and draws nothing.": "فاصلهٔ بین رکوردهای یک ردیف. خالی («خودکار»): {gap} px، که اگر فاصله‌های یک ردیف بیش از {share}% عرض آن را بگیرند، در آن ردیف کوچک‌تر می‌شود. فاصله‌ای که وارد کنید نگه داشته می‌شود؛ اگر ردیفی جای آن را نداشته باشد، عملیات «تولید نقشه» متوقف می‌شود و چیزی ترسیم نمی‌شود.",
