  "Generate again to choose a fix, or change the label settings.": "برای انتخاب راه رفع، نقشه را دوباره تولید کنید یا تنظیمات برچسب را تغییر دهید.",
  "Generate again to compute this choice.": "برای محاسبهٔ این گزینه، نقشه را دوباره تولید کنید.",
  "Generate again to refresh feature location metadata before rotating this record.": "پیش از چرخاندن این رکورد، برای تازه‌سازی فرادادهٔ مکان ویژگی، نقشه را دوباره تولید کنید.",
