  "Halo draws a white outline around the letters of each label with a leader, so leaders behind them are cut away. Box draws a white box behind the letters. None draws neither.": "گزینهٔ «هاله» دور حروف هر برچسب دارای خط رابط یک خط دور سفید می‌کشد، به‌طوری که خط‌های رابط پشت آن‌ها بریده می‌شوند. گزینهٔ «کادر» پشت حروف یک کادر سفید می‌کشد. گزینهٔ «هیچ‌کدام» هیچ‌یک از این دو را نمی‌کشد.",
  "Hatch": "هاشور",
  "Head Length Ratio": "نسبت طول سر",
  "Head length and shaft width apply to Arrow features and remain available even when no feature currently uses that rendering.": "طول سر و عرض بدنه برای ویژگی‌هایی با ترسیم پیکان اعمال می‌شود و حتی وقتی هیچ ویژگی از این ترسیم استفاده نکند، در دسترس می‌ماند.",
  "Head length divided by the full rendered feature thickness. Leave blank for Auto. Auto starts from the mode-specific default and lengthens the head as the shaft narrows.": "طول سر تقسیم بر ضخامت کامل ویژگی ترسیم‌شده. برای «خودکار» خالی بگذارید. با خالی ماندن فیلد (خودکار)، طول سر از پیش‌فرض مخصوص هر حالت شروع می‌شود و با باریک شدن بدنه بلندتر می‌شود.",
  "Heatmap": "نقشهٔ حرارتی",
  "Height": "ارتفاع",
  "Height must be a positive number of pixels (px optional).": "ارتفاع باید عددی مثبت بر حسب پیکسل باشد (واحد px اختیاری است).",
  "Height of the feature blocks.": "ارتفاع بلوک‌های ویژگی.",
  "Height of the linear GC content and GC skew tracks. Applies to whichever of those tracks are enabled when the diagram is generated.": "ارتفاع ترک‌های محتوای GC و GC skew در نقشهٔ خطی. برای هر یک از این ترک‌ها که هنگام تولید نقشه فعال باشد اعمال می‌شود.",
  "Height of this linear depth coverage track in px. Leave blank for auto.": "ارتفاع این ترک عمق نقشهٔ خطی بر حسب px. برای مقدار خودکار خالی بگذارید.",
