  "Its text is set in {names}, which are not part of gbdraw and are not loaded in this page.": {"one": "متن این نشست با قلم‌های {names} تنظیم شده است که بخشی از gbdraw نیستند و در این صفحه بارگذاری نشده‌اند.", "other": "متن این نشست با قلم‌های {names} تنظیم شده است که بخشی از gbdraw نیستند و در این صفحه بارگذاری نشده‌اند."},
  "Its text is set in {names}, which is not part of gbdraw and is not loaded in this page.": "متن این نشست با قلم {names} تنظیم شده است که بخشی از gbdraw نیست و در این صفحه بارگذاری نشده است.",
