  "Label TSV value patterns use case-insensitive Python regex. Examples: {example} and {otherExample}.": "الگوهای مقدار فایل TSV برچسب از عبارت باقاعدهٔ Python بدون حساسیت به حروف کوچک و بزرگ استفاده می‌کنند. نمونه‌ها: {example} و {otherExample}.",
  "Label Text Scope": "دامنهٔ تغییر متن برچسب",
  "Label fewer features, use a smaller Label Font Size, or draw a Linear map.": "ویژگی‌های کمتری را برچسب‌گذاری کنید، مقدار کوچک‌تری برای فیلد «اندازهٔ قلم برچسب» انتخاب کنید یا نقشهٔ خطی ترسیم کنید.",
  "Label fewer features: Blacklist or Whitelist under LABEL FILTERING.": "ویژگی‌های کمتری را برچسب‌گذاری کنید: در بخش «فیلتر برچسب‌ها» از گزینهٔ «فهرست سیاه» یا «فهرست سفید» استفاده کنید.",
