  "Labels are set to \"None\" (\"Show Labels\" or \"Label Mode\"), so only a feature with Label visibility \"On\" has one.": "برچسب‌ها روی گزینهٔ «هیچ‌کدام» تنظیم شده‌اند (فیلد «نمایش برچسب‌ها» یا «حالت برچسب»)، بنابراین فقط ویژگی‌ای برچسب دارد که فیلد «قابلیت مشاهدهٔ برچسب» آن روی گزینهٔ «روشن» باشد.",
