  "Larger than the requested {size} after moves of the Legend, title, or scale, which the fit does not include.": "پس از جابه‌جایی راهنما، عنوان یا مقیاس، بزرگ‌تر از اندازهٔ درخواست‌شده ({size}) است؛ این جابه‌جایی‌ها در متناسب‌سازی در نظر گرفته نمی‌شوند.",
