  "Legend: entries {items} had a color the app does not accept and were dropped.": {"one": "راهنما: موارد {items} رنگی داشتند که برنامه نمی‌پذیرد و کنار گذاشته شدند.", "other": "راهنما: موارد {items} رنگی داشتند که برنامه نمی‌پذیرد و کنار گذاشته شدند."},
  "Legend: entries {items} repeat an earlier entry of their list and were dropped.": {"one": "راهنما: موارد {items} تکرار موارد قبلی فهرست خود هستند و کنار گذاشته شدند.", "other": "راهنما: موارد {items} تکرار موارد قبلی فهرست خود هستند و کنار گذاشته شدند."},
  "Legend: entry {items} had a color the app does not accept and was dropped.": "راهنما: مورد {items} رنگی داشت که برنامه نمی‌پذیرد و کنار گذاشته شد.",
  "Legend: entry {items} repeats an earlier entry of its list and was dropped.": "راهنما: مورد {items} تکرار یکی از موارد قبلی فهرست خود است و کنار گذاشته شد.",
  "Legend: the color edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "راهنما: ویرایش رنگ ذخیره‌شده برای مورد «{label}» ({path}) به ردیف راهنما «{used}» منتقل می‌شود که ویرایش مخصوص خود را دارد؛ همان ویرایش استفاده می‌شود و این ویرایش کنار گذاشته شد.",
  "Legend: the color edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "راهنما: ویرایش رنگ ذخیره‌شده برای مورد «{label}» ({path}) ردیف راهنما «{used}» را تعیین می‌کند که ویرایش بعدی هم آن را تعیین می‌کند؛ ویرایش بعدی استفاده می‌شود و این ویرایش کنار گذاشته شد.",
  "Legend: the entry stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an entry of its own; that entry is used and this one was dropped.": "راهنما: مورد ذخیره‌شده برای «{label}» ({path}) به ردیف راهنما «{used}» منتقل می‌شود که مورد مخصوص خود را دارد؛ همان مورد استفاده می‌شود و این مورد کنار گذاشته شد.",
  "Legend: the entry stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "راهنما: مورد ذخیره‌شده برای «{label}» ({path}) ردیف راهنما «{used}» را تعیین می‌کند که ویرایش بعدی هم آن را تعیین می‌کند؛ ویرایش بعدی استفاده می‌شود و این مورد کنار گذاشته شد.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; it is not used.": "راهنما: موقعیت «{stored}» ({path}) یکی از موقعیت‌های حالت آن نیست؛ استفاده نمی‌شود.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; {used} is used.": "راهنما: موقعیت «{stored}» ({path}) یکی از موقعیت‌های حالت آن نیست؛ از موقعیت {used} استفاده می‌شود.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "راهنما: ویرایش خط دور ذخیره‌شده برای مورد «{label}» ({path}) به ردیف راهنما «{used}» منتقل می‌شود که ویرایش مخصوص خود را دارد؛ همان ویرایش استفاده می‌شود و این ویرایش کنار گذاشته شد.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "راهنما: ویرایش خط دور ذخیره‌شده برای مورد «{label}» ({path}) ردیف راهنما «{used}» را تعیین می‌کند که ویرایش بعدی هم آن را تعیین می‌کند؛ ویرایش بعدی استفاده می‌شود و این ویرایش کنار گذاشته شد.",
