  "Linear vertical spacing after the track, in pixels (px optional; nonnegative). Leave blank for the automatic spacing.": "فاصله‌گذاری عمودی پس از ترک در نقشهٔ خطی، بر حسب پیکسل (px اختیاری؛ عدد نامنفی). برای فاصله‌گذاری خودکار خالی بگذارید.",
  "Link Linear scale and ruler label font sizes": "پیوند دادن اندازه‌های قلم مقیاس نقشهٔ خطی و برچسب خط‌کش",
  "Link Scale and Ruler Label Font Sizes": "پیوند دادن اندازه‌های قلم مقیاس و برچسب خط‌کش",
  "List all 12 standard BLAST outfmt 6 fields in the \"{header}\" line, or remove the line so that the first 12 columns are read in the standard order.": "تمام 12 فیلد استاندارد BLAST outfmt 6 را در سطر «{header}» فهرست کنید یا آن سطر را بردارید تا 12 ستون اول به ترتیب استاندارد خوانده شوند.",
  "Live edit applying: geometry is being updated. Direct edits already applied are kept.": "در حال اعمال ویرایش زنده: هندسه در حال به‌روزرسانی است. ویرایش‌های مستقیم اعمال‌شده نگه داشته می‌شوند.",
  "Live edit failed: direct edits already applied are kept; geometry may still need updating.": "ویرایش زنده انجام نشد: ویرایش‌های مستقیمی که از قبل اعمال شده‌اند نگه داشته می‌شوند؛ ممکن است هندسه هنوز نیازمند به‌روزرسانی باشد.",
  "Live edit. Showing a track applies on Generate if the Result did not draw it when its Session was loaded; after a Depth file or series change, or a change of the records the Depth files map to; for a custom stack row added since the last Generate or a stack the last Generate could not build; and, with a Circular custom track stack or Circular track widths or radii, when Hide GC Content or Hide GC Skew is turned off.": "ویرایش زنده. نمایش یک ترک هنگام تولید اعمال می‌شود اگر نتیجه هنگام بارگذاری نشست آن را ترسیم نکرده باشد؛ پس از تغییر فایل عمق یا سری، یا تغییر رکوردهایی که فایل‌های عمق به آن‌ها پیوست شده‌اند؛ برای ردیف پشتهٔ سفارشی که پس از آخرین تولید افزوده شده است یا پشته‌ای که آخرین تولید نتوانسته آن را بسازد؛ و، با پشتهٔ ترک سفارشی نقشهٔ حلقوی یا با عرض یا شعاع ترک‌ها در نقشهٔ حلقوی، هنگامی که گزینهٔ «پنهان کردن محتوای GC» یا «پنهان کردن GC skew» غیرفعال شود.",
  "Live edit: feature color, label text, and visibility update the current Result; geometry may rerender automatically.": "ویرایش زنده: رنگ ویژگی، متن برچسب و قابلیت مشاهده، نتیجهٔ فعلی را به‌روزرسانی می‌کنند؛ ممکن است هندسه به‌طور خودکار دوباره ترسیم شود.",
  "Live edit: legend text, order, stroke, and removal update the current Result.": "ویرایش زنده: متن راهنما، ترتیب، خط دور و برداشتن، نتیجهٔ فعلی را به‌روزرسانی می‌کنند.",
  "Live edit: the padding updates the current Result.": "ویرایش زنده: حاشیه، نتیجهٔ فعلی را به‌روزرسانی می‌کند.",
  "Live edit; the position applies on Generate after the Multi-Record Canvas change.": "ویرایش زنده؛ موقعیت پس از تغییر تنظیم «بوم چندرکوردی» هنگام تولید اعمال می‌شود.",
  "Live edit; the position applies on Generate after the One circle change.": "ویرایش زنده؛ موقعیت پس از تغییر تنظیم «یک دایره» هنگام تولید اعمال می‌شود.",
