  "Load with {substitutes}: the Session opens and its text is drawn in {substitutes}, the nearest available fonts.": {"one": "بارگذاری با قلم‌های {substitutes}: نشست باز می‌شود و متن آن با قلم‌های {substitutes}، نزدیک‌ترین قلم‌های در دسترس، ترسیم می‌شود.", "other": "بارگذاری با قلم‌های {substitutes}: نشست باز می‌شود و متن آن با قلم‌های {substitutes}، نزدیک‌ترین قلم‌های در دسترس، ترسیم می‌شود."},
