  "Make the figure larger (Figure size in Layout).": "شکل را بزرگ‌تر کنید (تنظیم «اندازهٔ شکل» در بخش «طرح‌بندی»).",
  "Make the figure larger: Figure height about {height} (Figure size in Layout).": "شکل را بزرگ‌تر کنید: فیلد «ارتفاع شکل» حدود {height} (تنظیم «اندازهٔ شکل» در بخش «طرح‌بندی»).",
  "Make the figure larger: Figure width about {width} (Figure size in Layout).": "شکل را بزرگ‌تر کنید: فیلد «عرض شکل» حدود {width} (تنظیم «اندازهٔ شکل» در بخش «طرح‌بندی»).",
  "Make the figure larger: Figure width about {width}, Figure height about {height} (Figure size in Layout).": "شکل را بزرگ‌تر کنید: فیلد «عرض شکل» حدود {width}، فیلد «ارتفاع شکل» حدود {height} (تنظیم «اندازهٔ شکل» در بخش «طرح‌بندی»).",
  "Make the figure larger: increase Figure height (Figure size in Layout).": "شکل را بزرگ‌تر کنید: مقدار فیلد «ارتفاع شکل» را افزایش دهید (تنظیم «اندازهٔ شکل» در بخش «طرح‌بندی»).",
  "Make the figure larger: increase Figure width (Figure size in Layout).": "شکل را بزرگ‌تر کنید: مقدار فیلد «عرض شکل» را افزایش دهید (تنظیم «اندازهٔ شکل» در بخش «طرح‌بندی»).",
  "Make the figure larger: increase Figure width and Figure height (Figure size in Layout).": "شکل را بزرگ‌تر کنید: مقدار فیلدهای «عرض شکل» و «ارتفاع شکل» را افزایش دهید (تنظیم «اندازهٔ شکل» در بخش «طرح‌بندی»).",
  "Manual order and row assignment for multi-record canvas. Use Up/Down for left-to-right order within each row.": "ترتیب دستی و اختصاص ردیف برای بوم چندرکوردی. برای ترتیب از چپ به راست در هر ردیف از دکمه‌های «بالا» و «پایین» استفاده کنید.",
  "Manual scale interval for circular mode (in bp; must be > 0). Overrides automatic calculation.": "بازهٔ دستی مقیاس برای حالت حلقوی (بر حسب bp؛ باید بزرگ‌تر از 0 باشد). محاسبهٔ خودکار را بازنویسی می‌کند.",
  "Manual tick interval for Ruler scale style in bp (must be > 0). Leave blank to calculate automatically.": "بازهٔ دستی تیک برای سبک مقیاس «خط‌کش» بر حسب bp (باید بزرگ‌تر از 0 باشد). برای محاسبهٔ خودکار خالی بگذارید.",
  "Marks": "نشانه‌ها",
  "Match depth references to the selected record.": "توالی‌های مرجع عمق را با رکورد انتخاب‌شده تطبیق دهید.",
  "Match height": "ارتفاع تطابق",
