  "Matched sequences": "توالی‌های دارای تطابق",
  "Matched {detail}": "یافته در {detail}",
  "Max hits per protein for groups": "حداکثر تطابق‌ها برای هر پروتئین در گروه‌ها",
  "Max target seqs": "حداکثر توالی‌های هدف",
  "Max unit gap": "حداکثر فاصلهٔ واحد",
  "Maximum GC percentage for percent-mode clipping and axis scaling.": "حداکثر درصد GC برای محدودسازی و مقیاس‌بندی محور در حالت درصد.",
  "Maximum depth for clipping and normalization. Leave blank for auto.": "حداکثر عمق برای محدودسازی و نرمال‌سازی. برای مقدار خودکار خالی بگذارید.",
  "Maximum distinct subject proteins, not counting the protein itself, kept per query protein in each directed record-pair search to construct Similarity groups and Collinear blocks after result filtering. Leave blank to keep all hits passing the result filters. This does not limit raw LOSATP candidates or Pairwise display matches.": "حداکثر تعداد پروتئین‌های subject متمایز، بدون احتساب خود پروتئین، که پس از فیلتر نتایج برای هر پروتئین query در هر جستجوی جهت‌دار جفت رکورد برای ساخت گروه‌های شباهت و بلوک‌های هم‌خط نگه داشته می‌شود. برای نگه داشتن همهٔ تطابق‌هایی که از فیلترهای نتیجه عبور می‌کنند، خالی بگذارید. این مقدار نامزدهای خام LOSATP یا تطابق‌های نمایش دوبه‌دو را محدود نمی‌کند.",
  "Maximum filtered matches displayed per query protein in Pairwise mode. This does not limit LOSATP candidates or Similarity/Collinear member evidence.": "حداکثر تطابق‌های فیلترشدهٔ نمایش‌داده‌شده برای هر پروتئین query در حالت «تطابق‌های دوبه‌دو». این مقدار نامزدهای LOSATP یا شواهد اعضای گروه‌های شباهت و بلوک‌های هم‌خط را محدود نمی‌کند.",
  "Maximum number of units (loci, or CDSs without a locus identifier; see Unit mode) between neighboring anchors of one block, on both records. 0 joins adjacent units only. With Diagonal drift 0, a gap is bridged only when both records skip the same number of units.": "حداکثر تعداد واحدها (جایگاه‌ها یا ویژگی‌های CDS بدون شناسهٔ جایگاه؛ فیلد «حالت واحد» را ببینید) بین لنگرهای مجاور یک بلوک، در هر دو رکورد. 0 فقط واحدهای مجاور را به هم وصل می‌کند. اگر فیلد «رانش قطری» برابر 0 باشد، یک فاصله فقط وقتی پل زده می‌شود که در هر دو رکورد تعداد واحدهای ردشده یکسان باشد.",
  "Members": "اعضا",
