  "Minimum Length": "حداقل طول",
  "Minimum connected genes required for a Collinear ribbon.": "حداقل تعداد ژن‌های متصل لازم برای یک روبان هم‌خط.",
  "Minimum depth for clipping and normalization. Leave blank for auto.": "حداقل عمق برای محدودسازی و نرمال‌سازی. برای مقدار خودکار خالی بگذارید.",
  "Minimum label-to-label vertical spacing for circular layouts in px.": "حداقل فاصله‌گذاری عمودی بین برچسب‌ها در طرح‌بندی‌های نقشهٔ حلقوی بر حسب px.",
  "Minimum reserved height for the measured feature band, in pixels (px optional; positive). The actual reservation is max(measured, configured); this does not change feature glyph thickness, which is controlled by Feature Height ({option}). Auto values vary by record.": "حداقل ارتفاع رزروشده برای نوار اندازه‌گیری‌شدهٔ ویژگی، بر حسب پیکسل (px اختیاری؛ عدد مثبت). ارتفاع رزروشدهٔ واقعی برابر max(measured, configured) است؛ این مقدار ضخامت نماد ویژگی را تغییر نمی‌دهد. ضخامت با فیلد «ارتفاع ویژگی» ({option}) کنترل می‌شود. مقادیر «خودکار» از رکوردی به رکورد دیگر متفاوت‌اند.",
