  "Move the track, reduce widths, disable conflicting labels, or place it on the other side of the Axis.": "ترک را جابه‌جا کنید، عرض‌ها را کاهش دهید، برچسب‌های مزاحم را غیرفعال کنید یا آن را در سمت دیگر محور قرار دهید.",
