  "Multi-Record Canvas": "بوم چندرکوردی",
  "Multi-Record Canvas uses a grid. Turn it off to select one record.": "با فعال بودن گزینهٔ «بوم چندرکوردی»، از شبکه استفاده می‌شود. برای انتخاب یک رکورد، علامت کادر انتخاب آن را بردارید.",
  "Name": "نام",
  "Name / Species": "نام / گونه",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. Leave blank for the default name: Depth, or Depth N when there are several series.": "نام سری عمقی که این ردیف ترسیم می‌کند. با تایپ کردن، نام سری در همه‌جا تغییر می‌کند: در کارت سری، در هر ردیفی که آن را ترسیم می‌کند و در راهنما. برای نام پیش‌فرض خالی بگذارید: Depth یا Depth N هنگامی که چند سری وجود دارد.",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. The legend lists series in custom-stack order and omits series that no enabled row draws. Leave blank for the default name: Depth, or Depth N when there are several series.": "نام سری عمقی که این ردیف ترسیم می‌کند. با تایپ کردن، نام سری در همه‌جا تغییر می‌کند: در کارت سری، در هر ردیفی که آن را ترسیم می‌کند و در راهنما. راهنما سری‌ها را به ترتیب پشتهٔ سفارشی فهرست می‌کند و سری‌هایی را که هیچ ردیف فعالی ترسیم نمی‌کند کنار می‌گذارد. برای نام پیش‌فرض خالی بگذارید: Depth یا Depth N هنگامی که چند سری وجود دارد.",
  "Name of this Depth series in the legend. The legend label field of every Depth row that draws this series edits the same name. Leave blank for the default name: Depth, or Depth N when there are several series.": "نام این سری عمق در راهنما. فیلد «برچسب راهنما» در هر ردیف عمقی که این سری را ترسیم می‌کند، همین نام را ویرایش می‌کند. برای نام پیش‌فرض خالی بگذارید: Depth یا Depth N هنگامی که چند سری وجود دارد.",
  "Name of this row in the diagram legend. Leave blank to use the caption of its track, or else its query in words.": "نام این ردیف در راهنمای نقشه. برای استفاده از شرح ترک آن خالی بگذارید؛ اگر ترک شرحی نداشته باشد، توصیف جستار آن با کلمات استفاده می‌شود.",
  "Name suggestions ({count})": "پیشنهادهای نام ({count})",
  "Names for all records in this file": "نام‌ها برای همهٔ رکوردهای این فایل",
