  "No diagram is shown. Generate a diagram, then load the Feature Edits TSV.": "هیچ نقشه‌ای نمایش داده نمی‌شود. نقشه‌ای تولید کنید، سپس فایل TSV ویرایش‌های ویژگی را بارگذاری کنید.",
  "No editable feature label for this feature in current diagram.": "برای این ویژگی در نقشهٔ فعلی برچسب قابل ویرایشی وجود ندارد.",
  "No editable label": "برچسبی برای ویرایش وجود ندارد",
