  "No label shown (matches the label blacklist).": "برچسبی نمایش داده نمی‌شود (با فهرست سیاه برچسب مطابقت دارد).",
  "No label shown (not in the label whitelist).": "برچسبی نمایش داده نمی‌شود (در فهرست سفید برچسب نیست).",
  "No label shown (the feature is hidden).": "برچسبی نمایش داده نمی‌شود (ویژگی پنهان است).",
  "No label shown.": "برچسبی نمایش داده نمی‌شود.",
  "No matches": "یافته‌ای نیست",
  "No nucleotide sequence available.": "توالی نوکلئوتیدی در دسترس نیست.",
  "No pair has a BLAST TSV yet, so Generate draws no comparison. Choose a file for a pair under Selected pairs.": "هنوز هیچ جفتی فایل BLAST TSV ندارد، بنابراین عملیات «تولید نقشه» هیچ مقایسه‌ای ترسیم نمی‌کند. در بخش «جفت‌های انتخاب‌شده» برای یک جفت، فایلی انتخاب کنید.",
  "No qualifiers available.": "هیچ qualifier در دسترس نیست.",
  "No record ID matches the search.": "هیچ شناسهٔ رکوردی با جستجو مطابقت ندارد.",
  "No record has a feature that this selector names. Check the key and the value, for example {example}.": "هیچ رکوردی ویژگی‌ای ندارد که این انتخاب‌گر به آن اشاره کند. کلید و مقدار را بررسی کنید، برای مثال {example}.",
  "No record in the current input matches the record selector '{selector}'.": "هیچ رکوردی در ورودی فعلی با انتخاب‌گر رکورد «{selector}» مطابقت ندارد.",
  "No record is reversed yet. Choose a direction in each card.": "هنوز هیچ رکوردی معکوس نشده است. در هر کارت یک جهت انتخاب کنید.",
  "No record is reversed.": "هیچ رکوردی معکوس نمی‌شود.",
  "No record pair to compare. Records on the same Linear row are not compared: give each record its own row under Advanced comparison and layout (Record Layout), or add a sequence.": "هیچ جفت رکوردی برای مقایسه وجود ندارد. رکوردهای واقع در یک ردیف نقشهٔ خطی مقایسه نمی‌شوند: در بخش «مقایسه و طرح‌بندی پیشرفته» (بخش «طرح‌بندی رکورد») به هر رکورد ردیف مخصوص خود را بدهید یا یک توالی اضافه کنید.",
  "No records were found. Choose input containing records.": "هیچ رکوردی یافت نشد. ورودی‌ای شامل رکورد انتخاب کنید.",
  "No rendered features in selection.": "هیچ ویژگی ترسیم‌شده‌ای انتخاب نشد.",
  "No row matched a label of the diagram.": "هیچ ردیفی با برچسبی از نقشه منطبق نشد.",
  "No sequence available": "توالی در دسترس نیست",
  "No sequence source matched record “{id}”.": "هیچ منبع توالی‌ای با رکورد «{id}» مطابقت نداشت.",
  "No setting in this dialog makes these labels fit.": "هیچ تنظیمی در این کادر گفتگو باعث جا شدن این برچسب‌ها نمی‌شود.",
  "No successful Result is available yet. Correct the cause and retry.": "هنوز هیچ نتیجهٔ موفقی در دسترس نیست. علت را برطرف کنید و دوباره امتحان کنید.",
  "No usable candidate": "نامزد قابل استفاده‌ای وجود ندارد",
  "No usable candidate in this record.": "در این رکورد نامزد قابل استفاده‌ای وجود ندارد.",
  "No value found within {count} second.": "در {count} ثانیه مقداری یافت نشد.",
  "No value found within {count} seconds.": {"one": "در {count} ثانیه مقداری یافت نشد.", "other": "در {count} ثانیه مقداری یافت نشد."},
  "No window found. The thresholds removed {count} alignment.": "پنجره‌ای یافت نشد. {count} هم‌ترازی بر اساس آستانه‌ها برداشته شد.",
  "No window found. The thresholds removed {count} alignments.": {"one": "پنجره‌ای یافت نشد. {count} هم‌ترازی بر اساس آستانه‌ها برداشته شد.", "other": "پنجره‌ای یافت نشد. {count} هم‌ترازی بر اساس آستانه‌ها برداشته شد."},
  "None": "هیچ‌کدام",
  "None (Default)": "هیچ‌کدام (پیش‌فرض)",
  "Normal": "معمولی",
  "Normalize Record Lengths": "نرمال‌سازی طول رکوردها",
