  "Not added:": "اضافه نمی‌شوند:",
  "Not aligned": "ترازنشده",
  "Not applied": "اعمال‌نشده",
  "Not applied.": "اعمال نشد.",
  "Not applied: label text, label visibility, or feature visibility changed while the table loaded. The changes were kept. Load the table again.": "اعمال نشد: متن برچسب، قابلیت مشاهدهٔ برچسب یا قابلیت مشاهدهٔ ویژگی هنگام بارگذاری جدول تغییر کرد. تغییرها نگه داشته شدند. جدول را دوباره بارگذاری کنید.",
  "Not applied: the displayed diagram changed while the table loaded. Load the table again.": "اعمال نشد: نقشهٔ نمایش‌داده‌شده هنگام بارگذاری جدول تغییر کرد. جدول را دوباره بارگذاری کنید.",
  "Not applied: {inputs} changed while the table loaded. Load the table again.": "اعمال نشد: {inputs} هنگام بارگذاری جدول تغییر کرد. جدول را دوباره بارگذاری کنید.",
  "Not applied; the existing label edits were kept.": "اعمال نشد؛ ویرایش‌های موجود برچسب‌ها نگه داشته شد.",
  "Not attached": "پیوست‌نشده",
  "Not available: the latest Align did not change any record direction.": "در دسترس نیست: آخرین عملیات «تراز کردن» جهت هیچ رکوردی را تغییر نداد.",
  "Not available: this Session does not record which directions the latest Align changed.": "در دسترس نیست: این نشست ثبت نکرده است که آخرین عملیات «تراز کردن» کدام جهت‌ها را تغییر داده است.",
  "Not carried to the new drawing:": "به ترسیم جدید منتقل نمی‌شوند:",
  "Not carried to {drawing}:": "به ترسیم {drawing} منتقل نمی‌شوند:",
  "Not computed.": "محاسبه نشده است.",
  "Not found: {genes}.": "یافت نشد: {genes}.",
  "Not inspected": "بررسی‌نشده",
  "Not moved": "جابه‌جا نشده",
  "Not moved: {reason}": "جابه‌جا نشده: {reason}",
  "Not selected": "انتخاب‌نشده",
  "Not selected: adds no gene that the selected windows do not cover.": "انتخاب نشد: ژنی نمی‌افزاید که پنجره‌های انتخاب‌شده پوشش نداده باشند.",
  "Not selected: adds too few genes.": "انتخاب نشد: تعداد ژن‌هایی که می‌افزاید کمتر از حد لازم است.",
  "Not selected: over the limit of {count} windows of a file.": "انتخاب نشد: بیش از حد مجاز {count} پنجره در یک فایل.",
  "Not used · {name}": "استفاده‌نشده · {name}",
  "Note": "یادداشت",
  "Nothing changes until Apply. Cancel keeps the current diagram.": "تا عملیات «اعمال» انجام نشود، چیزی تغییر نمی‌کند. دکمهٔ «لغو» نقشهٔ فعلی را نگه می‌دارد.",
  "Nothing moved yet": "هنوز چیزی جابه‌جا نشده است",
  "Nothing was drawn.": "چیزی ترسیم نشد.",
  "Nothing was drawn. These labels need much more room than the map has, so placing them was not tried.": "چیزی ترسیم نشد. این برچسب‌ها به فضای بسیار بیشتری از فضای نقشه نیاز دارند، بنابراین جانمایی آن‌ها امتحان نشد.",
  "Nucleotide": "نوکلئوتید",
  "Nucleotide sequence": "توالی نوکلئوتیدی",
  "Number of records: {count} · {drawn} drawn": "تعداد رکوردها: {count} · {drawn} ترسیم‌شده",
  "Numbered Ticks": "تیک‌های شماره‌دار",
  "OFF": "خاموش",
  "ON aligns Linear definitions in a common left column. OFF centers them in a common column width and follows row offsets, including center or similarity alignment.": "اگر گزینه فعال باشد، تعریف‌های نقشهٔ خطی در یک ستون چپ مشترک تراز می‌شوند. اگر گزینه غیرفعال باشد، این تعریف‌ها در عرض ستونی مشترک وسط‌چین می‌شوند و جابه‌جایی‌های ردیف، از جمله ترازبندی در مرکز یا ترازبندی شباهت، را دنبال می‌کنند.",
  "Off": "خاموش",
  "Off (always hide)": "خاموش (همیشه پنهان)",
  "Off (hide; leave out of protein search)": "خاموش (پنهان؛ کنار گذاشتن از جستجوی پروتئین)",
  "Offset is outside the supported integer range.": "جابه‌جایی خارج از محدودهٔ اعداد صحیح پشتیبانی‌شده است.",
  "Offset must be a signed whole number of base pairs.": "جابه‌جایی باید عدد صحیح علامت‌دار (بر حسب bp) باشد.",
  "Offset must be a whole number of base pairs within the supported range.": "جابه‌جایی باید یک عدد صحیح (بر حسب bp) در محدودهٔ پشتیبانی‌شده باشد.",
  "Older undo history and the redo history were discarded to stay within the history limit.": "سابقهٔ واگرد قدیمی‌تر و سابقهٔ ازنو برای ماندن در حد مجاز سابقه دور انداخته شدند.",
  "Older undo history was discarded to stay within the history limit.": "سابقهٔ واگرد قدیمی‌تر برای ماندن در حد مجاز سابقه دور انداخته شد.",
