  "On applies when the label can be drawn.": "گزینهٔ «روشن» زمانی اعمال می‌شود که برچسب قابل ترسیم باشد.",
  "On axis": "روی محور",
  "On the same qualifier, the first matching rule wins.": "برای یک qualifier یکسان، اولین قانونی که مطابقت داشته باشد اعمال می‌شود.",
