  "One circle": "یک دایره",
  "One circle draws every record. Turn it off to select one record.": "با گزینهٔ «یک دایره»، همهٔ رکوردها ترسیم می‌شوند. برای انتخاب یک رکورد، علامت کادر انتخاب آن را بردارید.",
  "One color per 5 rings": "یک رنگ برای هر 5 حلقه",
  "One color per query": "یک رنگ برای هر توالی query",
  "One or more saved target anchors are no longer usable. Select or Skip each target.": "یک یا چند لنگر هدف ذخیره‌شده دیگر قابل استفاده نیستند. برای هر هدف، یک لنگر انتخاب کنید یا گزینهٔ «رد شدن» را انتخاب کنید.",
  "One row (auto)": "یک ردیف (خودکار)",
  "One rule for only this feature.": "یک قانون فقط برای این ویژگی.",
  "One rule per current similarity-group member.": "یک قانون برای هر عضو فعلی گروه شباهت.",
  "Only Features and Annotations rows can use On axis.": "فقط ردیف‌های «ویژگی‌ها» و «حاشیه‌نویسی‌ها» می‌توانند از گزینهٔ «روی محور» استفاده کنند.",
  "Only one enabled Features row is allowed.": "فقط یک ردیف فعال «ویژگی‌ها» مجاز است.",
  "Only show labels matching case-insensitive Python regex. Examples: {first} and {second}. Use {exact} for exact matches.": "فقط برچسب‌هایی را نشان دهید که با عبارت باقاعدهٔ Python بدون حساسیت به حروف کوچک و بزرگ مطابقت دارند. مثال‌ها: {first} و {second}. برای مطابقت دقیق از {exact} استفاده کنید.",
  "Only the records are added. Undo removes them in one step.": "فقط رکوردها اضافه می‌شوند. دستور «واگرد» آن‌ها را در یک مرحله برمی‌دارد.",
  "Only usable candidate": "تنها نامزد قابل استفاده",
  "Open": "باز کردن",
