  "Open active feature": "باز کردن ویژگی فعال",
  "Open an alignment review before applying.": "پیش از اعمال، بازبینی ترازبندی را شروع کنید.",
  "Open editor": "باز کردن ویرایشگر",
  "Open feature details": "باز کردن جزئیات ویژگی",
