  "Open similarity-group editor": "باز کردن ویرایشگر گروه شباهت",
  "Open the feature's popup and set Label visibility to Default, or change the setting that prevents its label.": "پنجرهٔ بازشوی ویژگی را باز کنید و فیلد «قابلیت مشاهدهٔ برچسب» را روی گزینهٔ «پیش‌فرض» بگذارید یا تنظیمی را که مانع نمایش برچسب آن می‌شود تغییر دهید.",
  "Open the first selected feature": "باز کردن اولین ویژگی انتخاب‌شده",
  "Open {label}": "باز کردن ژن {label}",
  "Open {label} ({product})": "باز کردن ژن {label} ({product})",
  "Operation error": "خطای عملیات",
  "Optional circular plot title used when the title position is Top or Bottom. Leave blank to use the default species + strain title.": "عنوان اختیاری نمودار نقشهٔ حلقوی که وقتی موقعیت عنوان روی گزینهٔ «بالا» یا «پایین» باشد استفاده می‌شود. برای استفاده از عنوان پیش‌فرض گونه + سویه خالی بگذارید.",
  "Optional fallback names for rings, one per source. Use new lines or commas.": "نام‌های جایگزین اختیاری برای حلقه‌ها، یکی برای هر منبع. از سطر جدید یا ویرگول استفاده کنید.",
  "Or keep the Legend color": "یا رنگ مورد راهنما را نگه دارید",
  "Organism": "جاندار",
