  "Outer gap": "فاصلهٔ خارجی",
  "Outer gap must be a nonnegative number of pixels (px optional).": "فاصلهٔ خارجی باید عددی نامنفی بر حسب پیکسل باشد (واحد px اختیاری است).",
  "Outer labels need about {ratio} times the room around the map.": "برچسب‌های خارجی به حدود {ratio} برابر فضای اطراف نقشه نیاز دارند.",
  "Output Prefix": "پیشوند خروجی",
  "Outside axis": "خارج محور",
  "Outward lane 1": "لاین 1 خارجی",
  "Overflow behavior": "رفتار سرریز",
  "Overlapping feature parts cannot be traversed safely.": "قسمت‌های هم‌پوشان ویژگی را نمی‌توان با اطمینان پیمایش کرد.",
  "Overlapping genomic features are assigned to additional lanes; other tracks are repacked automatically.": "ویژگی‌های ژنومی هم‌پوشان به لاین‌های اضافی اختصاص داده می‌شوند؛ ترک‌های دیگر به‌طور خودکار دوباره چیده می‌شوند.",
  "Overlay anchor": "روی لنگر",
  "Override the center-label reserved radius in px. Lower values let inside tracks move closer to the center, where they may overlap the label.": "شعاع رزروشدهٔ برچسب مرکز را بر حسب px بازنویسی کنید. مقادیر کمتر اجازه می‌دهند ترک‌های داخلی به مرکز نزدیک‌تر شوند، جایی که ممکن است با برچسب هم‌پوشانی داشته باشند.",
  "Overrides the inferred organism line for this Circular record. Leave empty to keep inference.": "سطر استنباط‌شدهٔ جاندار را برای این رکورد نقشهٔ حلقوی بازنویسی می‌کند. برای نگه داشتن مقدار استنباط‌شده، خالی بگذارید.",
  "Overrides the inferred strain line for this Circular record. Leave empty to keep inference.": "سطر استنباط‌شدهٔ سویه را برای این رکورد نقشهٔ حلقوی بازنویسی می‌کند. برای نگه داشتن مقدار استنباط‌شده، خالی بگذارید.",
  "PDF export error": "خطای صدور PDF",
  "PDF fonts cannot represent this text. Use SVG to retain this text.": "قلم‌های PDF نمی‌توانند این متن را نشان دهند. برای حفظ این متن از SVG استفاده کنید.",
  "PDF is limited to {limit} pt per side, and this figure is {width} x {height} pt.": "فایل PDF در هر ضلع به {limit} pt محدود است و این شکل {width} × {height} pt است.",
  "PNG export error": "خطای صدور PNG",
  "PNG is limited to {limit} px per side, and this figure is {width} x {height} px.": "فایل PNG در هر ضلع به {limit} px محدود است و این شکل {width} × {height} px است.",
  "PRESET SCHEMES": "طرح‌های پیش‌تنظیم",
  "Padding around annotation marks in pixels. Default: 2.": "حاشیهٔ پیرامون نشانه‌های حاشیه‌نویسی بر حسب پیکسل. پیش‌فرض: 2.",
  "Padding must be a nonnegative finite number.": "حاشیه باید عددی متناهی و نامنفی باشد.",
  "Paints the PNG background white. Turned off, the PNG keeps the transparent background of the drawing. SVG and PDF downloads have no background either way.": "پس‌زمینهٔ خروجی PNG را سفید می‌کند. با غیرفعال بودن این گزینه، خروجی PNG پس‌زمینهٔ شفاف ترسیم را نگه می‌دارد. بارگیری‌های SVG و PDF در هر دو حالت پس‌زمینه ندارند.",
  "Pair {pairs} is set to Upload BLAST TSV, so not every pair runs LOSAT.": "جفت {pairs} روی «بارگذاری فایل BLAST TSV» تنظیم شده است، بنابراین LOSAT برای برخی از جفت‌ها اجرا نمی‌شود.",
  "Pair: #{query} to #{subject}.": "جفت: از #{query} به #{subject}.",
  "Pairs between rows {upper} and {lower}": "جفت‌های بین ردیف‌های {upper} و {lower}",
  "Pairs {pairs} are set to Upload BLAST TSV, so not every pair runs LOSAT.": {"one": "جفت‌های {pairs} روی «بارگذاری فایل BLAST TSV» تنظیم شده‌اند، بنابراین LOSAT برای برخی از جفت‌ها اجرا نمی‌شود.", "other": "جفت‌های {pairs} روی «بارگذاری فایل BLAST TSV» تنظیم شده‌اند، بنابراین LOSAT برای برخی از جفت‌ها اجرا نمی‌شود."},
  "Pairwise Comparisons": "مقایسه‌های دوبه‌دو",
  "Pairwise comparison": "مقایسهٔ دوبه‌دو",
  "Pairwise display max hits": "حداکثر تطابق‌های نمایش دوبه‌دو",
  "Pairwise display max hits per protein": "حداکثر تطابق‌های نمایش دوبه‌دو برای هر پروتئین",
  "Pairwise match": "تطابق دوبه‌دو",
  "Pairwise match details": "جزئیات تطابق دوبه‌دو",
