  "Retry the live edit or use Generate.": "ویرایش زنده را دوباره امتحان کنید یا روی دکمهٔ «تولید نقشه» کلیک کنید.",
  "Retry the operation.": "عملیات را دوباره امتحان کنید.",
  "Return moved elements, canvas padding, pan, and zoom to their defaults": "بازگرداندن عناصر جابه‌جاشده، حاشیهٔ بوم، پیمایش و بزرگ‌نمایی به پیش‌فرض",
  "Reuse BLAST TSV for #{from} to #{to}": "استفادهٔ مجدد از فایل BLAST TSV برای مقایسه از #{from} به #{to}",
