  "Show primary coordinate ticks and labels in simple mode. The circular genome axis remains visible when this is off.": "تیک‌ها و برچسب‌های اصلی مختصات را در حالت ساده نمایش دهید. وقتی این گزینه غیرفعال باشد، محور ژنوم در نقشهٔ حلقوی همچنان نمایش داده می‌شود.",
