  "Show the bottom scale bar or ruler and any coordinate ticks and labels drawn on record axes. Main record axes remain visible when this is off.": "نوار یا خط‌کش مقیاس پایین و هر تیک و برچسب مختصات ترسیم‌شده روی محور رکوردها را نمایش دهید. وقتی این گزینه غیرفعال باشد، محور اصلی رکوردها همچنان نمایش داده می‌شود.",
  "Show the depth coverage axis line. Hiding the axis also hides depth tick marks and labels.": "خط محور عمق را نمایش دهید. پنهان کردن محور، تیک‌ها و برچسب‌های عمق را هم پنهان می‌کند.",
