  "Show this label": "نمایش این برچسب",
  "Show {name} to apply this alignment.": "برای اعمال این ترازبندی، ترسیم {name} را نمایش دهید.",
  "Showing and hiding apply at once; leaving a feature out of protein search applies on Generate.": "نمایش و پنهان کردن بلافاصله اعمال می‌شود؛ کنار گذاشتن یک ویژگی از جستجوی پروتئین هنگام تولید اعمال می‌شود.",
  "Showing the last successful Result again; your changes were not applied. Correct the cause and retry.": "آخرین نتیجهٔ موفق دوباره نمایش داده می‌شود؛ تغییرات شما اعمال نشد. علت را برطرف کنید و دوباره امتحان کنید.",
  "Showing the last successful Result; your changes were not applied.": "آخرین نتیجهٔ موفق نمایش داده می‌شود؛ تغییرات شما اعمال نشد.",
  "Showing the last successful result.": "آخرین نتیجهٔ موفق نمایش داده می‌شود.",
  "Shown drawing: {name}": "ترسیم نمایش‌داده‌شده: {name}",
  "Shown pane": "بخش نمایش‌داده‌شده",
  "Similarity alignment applied.": "ترازبندی شباهت اعمال شد.",
