  "Similarity group {id}: {summary}": "گروه شباهت {id}: {summary}",
  "Similarity groups": "گروه‌های شباهت",
  "Similarity groups and Collinear blocks compare every adjacent pair with LOSAT, so they do not run on pairs set one by one in Selected pairs. Choose Run LOSAT for all adjacent pairs, or choose Pairwise matches.": "حالت‌های «گروه‌های شباهت» و «بلوک‌های هم‌خط» هر جفت مجاور را با LOSAT مقایسه می‌کنند، بنابراین روی جفت‌هایی که جداگانه در بخش «جفت‌های انتخاب‌شده» تنظیم شده‌اند اجرا نمی‌شوند. گزینهٔ «اجرای LOSAT برای همهٔ جفت‌های مجاور» یا «تطابق‌های دوبه‌دو» را انتخاب کنید.",
  "Similarity groups and Collinear blocks compare every adjacent pair with LOSAT.": "حالت‌های «گروه‌های شباهت» و «بلوک‌های هم‌خط» هر جفت مجاور را با LOSAT مقایسه می‌کنند.",
  "Similarity groups appear after a Linear comparison with Similarity groups turned on.": "گروه‌های شباهت پس از مقایسهٔ نقشهٔ خطی با روشن بودن حالت «گروه‌های شباهت» نمایان می‌شوند.",
  "Similarity groups: {count} description edit ({path}) names a group the saved Result does not have and was dropped.": "گروه‌های شباهت: {count} ویرایش توضیحات ({path}) کنار گذاشته شد، زیرا به گروهی اشاره می‌کند که در نتیجهٔ ذخیره‌شده وجود ندارد.",
  "Similarity groups: {count} description edits ({path}) name a group the saved Result does not have and were dropped.": {"one": "گروه‌های شباهت: {count} ویرایش توضیحات ({path}) کنار گذاشته شد، زیرا به گروهی اشاره می‌کند که در نتیجهٔ ذخیره‌شده وجود ندارد.", "other": "گروه‌های شباهت: {count} ویرایش توضیحات ({path}) کنار گذاشته شد، زیرا به گروهی اشاره می‌کند که در نتیجهٔ ذخیره‌شده وجود ندارد."},
  "Similarity groups: {count} name edit ({path}) names a group the saved Result does not have and was dropped.": "گروه‌های شباهت: {count} ویرایش نام ({path}) کنار گذاشته شد، زیرا به گروهی اشاره می‌کند که در نتیجهٔ ذخیره‌شده وجود ندارد.",
  "Similarity groups: {count} name edits ({path}) name a group the saved Result does not have and were dropped.": {"one": "گروه‌های شباهت: {count} ویرایش نام ({path}) کنار گذاشته شد، زیرا به گروهی اشاره می‌کند که در نتیجهٔ ذخیره‌شده وجود ندارد.", "other": "گروه‌های شباهت: {count} ویرایش نام ({path}) کنار گذاشته شد، زیرا به گروهی اشاره می‌کند که در نتیجهٔ ذخیره‌شده وجود ندارد."},
  "Similarity-group match": "تطابق گروه شباهت",
  "Similarity-group member": "عضو گروه شباهت",
