  "Similarity-group member protein ID": "شناسهٔ پروتئین عضو گروه شباهت",
  "Simple mode only. Above places features above the axis, Features on axis centers them on it, and Below places them below it. Use Reset to copy this choice into the custom stack.": "فقط در حالت ساده. گزینهٔ «بالا» ویژگی‌ها را بالای محور قرار می‌دهد، گزینهٔ «ویژگی‌ها روی محور» مرکز آن‌ها را روی محور قرار می‌دهد و گزینهٔ «پایین» آن‌ها را پایین محور قرار می‌دهد. برای کپی این انتخاب در پشتهٔ سفارشی از دکمهٔ «بازنشانی» استفاده کنید.",
  "Simple mode only. Display a GC content track; use Reset to copy it into the custom stack.": "فقط در حالت ساده. یک ترک محتوای GC نمایش دهید؛ برای کپی آن در پشتهٔ سفارشی از دکمهٔ «بازنشانی» استفاده کنید.",
  "Simple mode only. Display a GC skew track; use Reset to copy it into the custom stack.": "فقط در حالت ساده. یک ترک GC skew نمایش دهید؛ برای کپی آن در پشتهٔ سفارشی از دکمهٔ «بازنشانی» استفاده کنید.",
  "Simple mode only. Display depth coverage tracks from uploaded TSV files; use Reset to copy them into the custom stack.": "فقط در حالت ساده. ترک‌های عمق را از فایل‌های TSV بارگذاری‌شده نمایش دهید؛ برای کپی آن‌ها در پشتهٔ سفارشی از دکمهٔ «بازنشانی» استفاده کنید.",
  "Simple mode only. Use Reset to rebuild the custom stack from this setting.": "فقط در حالت ساده. برای بازسازی پشتهٔ سفارشی از این تنظیم، از دکمهٔ «بازنشانی» استفاده کنید.",
