  "Strand": "رشته",
  "Strand: neighboring anchors of a block follow its strand orientation and the gene order. Gene order: they follow the gene order only.": "گزینهٔ «رشته»: لنگرهای مجاور یک بلوک از جهت‌گیری رشتهٔ آن و ترتیب ژن‌ها پیروی می‌کنند. گزینهٔ «ترتیب ژن‌ها»: فقط از ترتیب ژن‌ها پیروی می‌کنند.",
  "Stretch the overlay from its anchor to this slot, over every slot between them (to_slot). None: the overlay's own band.": "لایهٔ رویی را از لنگر آن تا این اسلات، روی همهٔ اسلات‌های میان آن‌ها، گسترش دهید (to_slot). «هیچ‌کدام»: نوار خود لایهٔ رویی.",
