  "Supply GenBank input or matching GFF3 and FASTA inputs.": "ورودی GenBank یا ورودی‌های GFF3 و FASTA منطبق را ارائه دهید.",
  "Supply a comparison sequence file (FASTA, GenBank, or DDBJ) or BLAST outfmt 6/7 as required.": "یک فایل توالی مقایسه (FASTA، GenBank یا DDBJ) یا فایل BLAST outfmt 6/7 را بر حسب نیاز ارائه دهید.",
