  "TSV file of rules: feature type, qualifier, regular expression, color, and optional legend name.": "فایل TSV قوانین: نوع ویژگی، qualifier، عبارت باقاعده، رنگ و نام راهنما (اختیاری).",
  "Tab-separated value (TSV) file of feature type and color. Feature types not listed keep the selected palette colors.": "فایل TSV (مقادیر جداشده با Tab) شامل نوع ویژگی و رنگ. نوع‌های ویژگی که در آن نیامده‌اند، رنگ‌های پالت انتخاب‌شده را نگه می‌دارند.",
