  "Track stack: the Depth row \"{label}\" ({path}) names a Depth series its drawing does not have; the row is turned off and no longer names that series.": "پشتهٔ ترک: ردیف عمق «{label}» ({path}) به یک سری عمق اشاره می‌کند که در ترسیم آن وجود ندارد؛ ردیف خاموش شد و دیگر به آن سری اشاره نمی‌کند.",
  "Track width: {px} px.": "عرض ترک: {px} px.",
  "Track {id} Legend name": "نام راهنمای ترک {id}",
  "Track {id} color": "رنگ ترک {id}",
