  "annotations that name a source feature have no current CLI projection.": "حاشیه‌نویسی‌هایی که به ویژگی منبع اشاره می‌کنند نگاشت به رابط CLI فعلی ندارند.",
  "batch or multiple-output semantics have no single current CLI projection.": "معنای اجرای دسته‌ای یا چندخروجی نگاشت واحدی به رابط CLI فعلی ندارد.",
