  "feature placements and feature edits require each input file to hold exactly one record or to have exactly one selected.": "برای جانمایی و ویرایش ویژگی‌ها، هر فایل ورودی باید دقیقاً یک رکورد داشته باشد یا دقیقاً یک رکورد از آن انتخاب شده باشد.",
  "feature strand {before} → {after}": "رشتهٔ ویژگی {before} ← {after}",
