  "gbdraw reads gzip files that expand to at most {limit} MiB.": "برنامهٔ gbdraw فایل‌های gzip را می‌خواند که اندازهٔ آن‌ها پس از خارج شدن از حالت فشرده حداکثر {limit} MiB باشد.",
  "gbdraw was updated while this page was open, so the comparison search did not run. Save a Session, reload the page, then run the search again.": "برنامهٔ gbdraw در مدتی که این صفحه باز بود به‌روزرسانی شد، بنابراین جستجوی مقایسه اجرا نشد. یک نشست ذخیره کنید، صفحه را بارگذاری مجدد کنید، سپس جستجو را دوباره اجرا کنید.",
