  "legend label": "برچسب راهنما",
  "location and record_location rows cannot be matched to {count} label on a cropped, reverse-complemented, or rotated record until the diagram records where it drew it. Generate the diagram again, then load the table.": "ردیف‌های location و record_location را نمی‌توان با {count} برچسب در رکورد برش‌خورده، مکمل معکوس‌شده یا چرخانده‌شده تطبیق داد، تا وقتی نقشه محل ترسیم آن را ثبت نکرده باشد. نقشه را دوباره تولید کنید و سپس جدول را بارگذاری کنید.",
  "location and record_location rows cannot be matched to {count} labels on cropped, reverse-complemented, or rotated records until the diagram records where it drew them. Generate the diagram again, then load the table.": {"one": "ردیف‌های location و record_location را نمی‌توان با {count} برچسب در رکوردهای برش‌خورده، مکمل معکوس‌شده یا چرخانده‌شده تطبیق داد، تا وقتی نقشه محل ترسیم آن‌ها را ثبت نکرده باشد. نقشه را دوباره تولید کنید و سپس جدول را بارگذاری کنید.", "other": "ردیف‌های location و record_location را نمی‌توان با {count} برچسب در رکوردهای برش‌خورده، مکمل معکوس‌شده یا چرخانده‌شده تطبیق داد، تا وقتی نقشه محل ترسیم آن‌ها را ثبت نکرده باشد. نقشه را دوباره تولید کنید و سپس جدول را بارگذاری کنید."},
  "megablast is fastest for highly similar nucleotide sequences; blastn is more sensitive.": "برای توالی‌های نوکلئوتیدی بسیار مشابه، megablast سریع‌ترین است و blastn حساس‌تر.",
