  "the CLI ruler labels follow {option}, while this render keeps the default ruler-label font sizes.": "برچسب‌های خط‌کش در CLI از گزینهٔ {option} پیروی می‌کنند، در حالی که این رندر اندازه‌های قلم پیش‌فرض برچسب‌های خط‌کش را نگه می‌دارد.",
  "the Legend row edits cannot be written as a {option} table.": "ویرایش‌های ردیف راهنما را نمی‌توان به‌صورت جدول {option} نوشت.",
