  "the command line lists no comparison table rows for this protein search mode.": "خط فرمان برای این حالت جستجوی پروتئین ردیف‌های جدول مقایسه را فهرست نمی‌کند.",
  "the command line lists no pairs of a protein search of every adjacent pair beside a BLAST table.": "خط فرمان در کنار جدول BLAST، جفت‌های جستجوی پروتئین برای همهٔ جفت‌های مجاور را فهرست نمی‌کند.",
  "the command line lists no protein search pairs of a record drawn in several windows.": "خط فرمان جفت‌های جستجوی پروتئین را برای رکوردی که در چند پنجره ترسیم می‌شود فهرست نمی‌کند.",
  "the command line takes no comparison file for a record drawn in several windows.": "خط فرمان برای رکوردی که در چند پنجره ترسیم می‌شود فایل مقایسه نمی‌پذیرد.",
  "the committed render cannot be represented safely by the current CLI.": "رندر ثبت‌شده را نمی‌توان به‌طور ایمن با رابط CLI فعلی بازنمایی کرد.",
  "the committed render has no source records.": "رندر ثبت‌شده رکورد منبعی ندارد.",
  "the committed render mixes source kinds that the CLI cannot combine.": "رندر ثبت‌شده انواع منبعی را با هم ترکیب می‌کند که CLI نمی‌تواند ترکیب کند.",
  "the committed render request is missing or invalid.": "درخواست رندر ثبت‌شده وجود ندارد یا نامعتبر است.",
  "the custom circular definition interval has no CLI option.": "فاصلهٔ سفارشی سطرهای تعریف نقشهٔ حلقوی گزینه‌ای در CLI ندارد.",
  "the first candidate in a fixed order; none stands out": "اولین نامزد در یک ترتیب ثابت؛ هیچ‌کدام برجسته نیست",
  "the interactive metadata policy has no current CLI projection.": "خط‌مشی فرادادهٔ تعاملی نگاشت به رابط CLI فعلی ندارد.",
  "the label blacklist is malformed.": "فهرست سیاه برچسب ساختار نامعتبر دارد.",
  "the only candidate with a reciprocal best hit": "تنها نامزدی که reciprocal best hit دارد",
