  "{complete} found in full, {partial} in part, {absent} not at all.": "{complete} ژن به‌طور کامل یافت شد، {partial} ژن به‌طور جزئی و {absent} ژن اصلاً یافت نشد.",
  "{confidence} confidence": "اطمینان {confidence}",
  "{count} Feature visibility edit from an older Session hid every feature with the same hash, such as each copy of a duplicated record. It now applies only to the feature that was edited, so the next Generate draws the others.": "{count} ویرایش قابلیت مشاهدهٔ ویژگی از نشست قدیمی‌تر همهٔ ویژگی‌های دارای هش یکسان را پنهان می‌کرد، مانند هر نسخه از یک رکورد تکثیرشده. این ویرایش اکنون فقط روی ویژگی ویرایش‌شده اعمال می‌شود، بنابراین هنگام تولید بعدی، بقیهٔ ویژگی‌ها ترسیم می‌شوند.",
  "{count} Feature visibility edits from an older Session hid every feature with the same hash, such as each copy of a duplicated record. Each now applies only to the feature that was edited, so the next Generate draws the others.": {"one": "{count} ویرایش قابلیت مشاهدهٔ ویژگی از نشست قدیمی‌تر همهٔ ویژگی‌های دارای هش یکسان را پنهان می‌کرد، مانند هر نسخه از یک رکورد تکثیرشده. هر کدام اکنون فقط روی ویژگی ویرایش‌شده اعمال می‌شود، بنابراین هنگام تولید بعدی، بقیهٔ ویژگی‌ها ترسیم می‌شوند.", "other": "{count} ویرایش قابلیت مشاهدهٔ ویژگی از نشست قدیمی‌تر همهٔ ویژگی‌های دارای هش یکسان را پنهان می‌کرد، مانند هر نسخه از یک رکورد تکثیرشده. هر کدام اکنون فقط روی ویژگی ویرایش‌شده اعمال می‌شود، بنابراین هنگام تولید بعدی، بقیهٔ ویژگی‌ها ترسیم می‌شوند."},
  "{count} TSV": "{count} فایل TSV",
  "{count} TSVs": {"one": "{count} فایل TSV", "other": "{count} فایل TSV"},
