  "{count} aligned": "{count} ترازشده",
  "{count} annotation from an older Session named a feature by {selector}. It now names that feature by its source, so it stays on the feature when the crop or orientation changes.": "{count} حاشیه‌نویسی از یک نشست قدیمی‌تر با انتخاب‌گر {selector} به یک ویژگی اشاره می‌کرد. اکنون با منبع آن ویژگی به آن اشاره می‌کند، بنابراین با تغییر برش یا جهت‌گیری روی همان ویژگی می‌ماند.",
  "{count} annotation of a selected feature that the current diagram does not draw was not exported.": "{count} حاشیه‌نویسی از یک ویژگی انتخاب‌شده‌ای که نقشهٔ فعلی آن را ترسیم نمی‌کند، صادر نشد.",
  "{count} annotation of a selected feature was written as {recordSelector} and {featureSelector}. It names the same feature only while the record order stays as drawn.": "{count} حاشیه‌نویسی از یک ویژگی انتخاب‌شده به‌صورت {recordSelector} و {featureSelector} نوشته شد. این حاشیه‌نویسی فقط تا زمانی به همان ویژگی اشاره می‌کند که ترتیب رکوردها همان‌طور که ترسیم شده است باقی بماند.",
  "{count} annotations from an older Session named a feature by {selector}. Each now names that feature by its source, so it stays on the feature when the crop or orientation changes.": {"one": "{count} حاشیه‌نویسی از یک نشست قدیمی‌تر با انتخاب‌گر {selector} به یک ویژگی اشاره می‌کرد. اکنون هر کدام با منبع آن ویژگی به آن اشاره می‌کند، بنابراین با تغییر برش یا جهت‌گیری روی همان ویژگی می‌ماند.", "other": "{count} حاشیه‌نویسی از یک نشست قدیمی‌تر با انتخاب‌گر {selector} به یک ویژگی اشاره می‌کرد. اکنون هر کدام با منبع آن ویژگی به آن اشاره می‌کند، بنابراین با تغییر برش یا جهت‌گیری روی همان ویژگی می‌ماند."},
  "{count} annotations of selected features that the current diagram does not draw were not exported.": {"one": "{count} حاشیه‌نویسی از ویژگی‌های انتخاب‌شده‌ای که نقشهٔ فعلی آن‌ها را ترسیم نمی‌کند، صادر نشد.", "other": "{count} حاشیه‌نویسی از ویژگی‌های انتخاب‌شده‌ای که نقشهٔ فعلی آن‌ها را ترسیم نمی‌کند، صادر نشد."},
  "{count} annotations of selected features were written as {recordSelector} and {featureSelector}. They name the same features only while the record order stays as drawn.": {"one": "{count} حاشیه‌نویسی از ویژگی‌های انتخاب‌شده به‌صورت {recordSelector} و {featureSelector} نوشته شد. این حاشیه‌نویسی‌ها فقط تا زمانی به همان ویژگی‌ها اشاره می‌کنند که ترتیب رکوردها همان‌طور که ترسیم شده است باقی بماند.", "other": "{count} حاشیه‌نویسی از ویژگی‌های انتخاب‌شده به‌صورت {recordSelector} و {featureSelector} نوشته شد. این حاشیه‌نویسی‌ها فقط تا زمانی به همان ویژگی‌ها اشاره می‌کنند که ترتیب رکوردها همان‌طور که ترسیم شده است باقی بماند."},
