  "{count} chosen features keep their current directions.": {"one": "{count} ویژگی انتخاب‌شده جهت فعلی خود را نگه می‌دارد.", "other": "{count} ویژگی انتخاب‌شده جهت فعلی خود را نگه می‌دارد."},
