  "{count} feature edits apply to features outside the current crop or display; they apply again when those features are drawn.": {"one": "{count} ویرایش ویژگی برای ویژگی‌هایی خارج از برش یا نمای فعلی اعمال می‌شود؛ هنگام ترسیم آن ویژگی‌ها دوباره اعمال می‌شود.", "other": "{count} ویرایش ویژگی برای ویژگی‌هایی خارج از برش یا نمای فعلی اعمال می‌شود؛ هنگام ترسیم آن ویژگی‌ها دوباره اعمال می‌شود."},
